# ==============================================================================
# Security Incident Response Automator (v1.1.52)
# Standalone Native Windows Form Application (Tabbed UI, Real Verification, Audit Trail)
# Domain Agnostic | Auto-Detect Domain | Remote / Non-Domain Workstation Support
# Native .NET System.DirectoryServices Fallback (Runs with or without RSAT!)
#
# DEVELOPER ARCHITECTURAL NAVIGATION INDEX:
#   [01] Single-Threaded Apartment (-STA) Auto-Enforcement   (Line ~30)
#   [02] Embedded Setup Batch Scripts (Base64 UTF-8)        (Line ~85)
#   [03] Domain Auto-Discovery & Connection Memory           (Line ~1460)
#   [04] Active Directory Dual-Engine & User Search          (Line ~1540 & ~2810)
#   [05] Microsoft Graph Identity & Session Revocation       (Line ~1750 & ~2040)
#   [06] Google Workspace (GAM7) Orchestration & Signout     (Line ~2150 & ~2490)
#   [07] Deep Isolation, Cloud MFA Wipe & KDC Hard-Lock      (Line ~3180 & ~4170)
#   [08] Mailbox Forwarding & Inbox Rule Remediation         (Line ~3850 & ~4070)
#   [09] Security Event Triage & Plain-English Decoder       (Line ~4450 & ~4840)
#   [10] Windows Forms 5-Tab GUI Architecture & Controls     (Line ~5270+)
#   [11] Domain Switcher, Changelog & Self-Updater Dialogs   (Line ~5940+)
#   [12] Dynamic Theme Engine (Light / Dark Mode)            (Line ~8600)
#   [13] High-DPI Responsive Scaling & Pixel Font Cache      (Line ~8740)
# ==============================================================================

#Requires -Version 5.1

if ([System.Threading.Thread]::CurrentThread.GetApartmentState() -ne [System.Threading.ApartmentState]::STA) {
    if ($MyInvocation.MyCommand -and $MyInvocation.MyCommand.Path) {
        $psExe = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
        if (-not (Test-Path -LiteralPath $psExe)) { $psExe = "powershell.exe" }
        Start-Process -FilePath $psExe -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA', '-File', "`"$($MyInvocation.MyCommand.Path)`"")
        exit 0
    }
}

$global:MaximumFunctionCount = 32768
$global:MaximumVariableCount = 32768
$script:AppVersion = "1.1.52"
$script:MainScriptPath = if ($MyInvocation.MyCommand -and $MyInvocation.MyCommand.Path) { $MyInvocation.MyCommand.Path } else { $PSCommandPath }

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.DirectoryServices

[System.Windows.Forms.Application]::EnableVisualStyles()

function Ensure-Win32ConsoleType {
    try {
        if (-not ('IncidentAutomator.Win32ConsoleFix' -as [type])) {
            Add-Type -Name Win32ConsoleFix -Namespace IncidentAutomator -MemberDefinition @'
[DllImport("kernel32.dll")]
public static extern IntPtr GetConsoleWindow();
[DllImport("user32.dll")]
public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
'@ -ErrorAction SilentlyContinue
        }
    } catch {}
}

function Hide-ConsoleWindowSafe {
    try {
        Ensure-Win32ConsoleType
        $consoleHwnd = [IncidentAutomator.Win32ConsoleFix]::GetConsoleWindow()
        if ($consoleHwnd -ne [IntPtr]::Zero) {
            [void][IncidentAutomator.Win32ConsoleFix]::ShowWindow($consoleHwnd, 0)
        }
    } catch {}
}

function Show-ConsoleWindowSafe {
    try {
        Ensure-Win32ConsoleType
        $consoleHwnd = [IncidentAutomator.Win32ConsoleFix]::GetConsoleWindow()
        if ($consoleHwnd -ne [IntPtr]::Zero) {
            [void][IncidentAutomator.Win32ConsoleFix]::ShowWindow($consoleHwnd, 5)
        }
    } catch {}
}

