    $btnCancelDlg.Text = "Cancel"
    $btnCancelDlg.Location = New-Object System.Drawing.Point(394, 350)
    $btnCancelDlg.Size = New-Object System.Drawing.Size(100, 32)
    $btnCancelDlg.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
