    $dlg.AcceptButton = $btnConnect
    $dlg.CancelButton = $btnCancelDlg
    $dlg.Add_Shown({
        if ($txtDlgPass.Enabled) { $txtDlgPass.Focus() }
    })

    $btnConnect.Add_Click({
        $target = $txtDlgServer.Text.Trim()
        if ([string]::IsNullOrEmpty($target)) {
            $lblDlgStatus.Text = "Please enter a target domain name or Domain Controller IP."
            return
        }

        $lblDlgStatus.Text = "Performing live LDAP RootDSE verification against '$target'..."
        $lblDlgStatus.ForeColor = [System.Drawing.Color]::FromArgb(2, 132, 199)
        $dlg.Refresh()

        try {
            $testServer = $target
            $testCred = if ($chkUseAlt.Checked) {
                if ([string]::IsNullOrEmpty($txtDlgUser.Text) -or [string]::IsNullOrEmpty($txtDlgPass.Text)) {
                    $lblDlgStatus.Text = "Username and password are required when using explicit credentials."
                    $lblDlgStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
                    return
                }
                $sec = ConvertTo-SecureString $txtDlgPass.Text -AsPlainText -Force
                New-Object System.Management.Automation.PSCredential($txtDlgUser.Text, $sec)
            } else {
                $null
            }

            $adDomainName = Get-ADDomainSafe -Server $testServer -Cred $testCred

            $script:targetDomain = $adDomainName
            $script:targetServer = $target
            if ($chkUseAlt.Checked) {
                $script:adCredential = $testCred
                $script:useExplicitCreds = $true
                $script:adminAccount = $txtDlgUser.Text
            } else {
                $script:adCredential = $null
                $script:useExplicitCreds = $false
                $script:adminAccount = "$env:USERNAME"
            }

            Save-LastDomainConnectionSafe -TargetDomain $script:targetDomain -TargetServer $script:targetServer -AdminUsername $script:adminAccount

            $lblSub.Text = "Domain: " + $script:targetDomain + " | DC: " + $script:targetServer + " | Admin: " + $script:adminAccount
            $lblStatusAD.Text = "Active Directory: VERIFIED ($($script:targetDomain) via $($script:targetServer))"
            $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)

            if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
                Update-IntegrationAlertBanner
            }

            Write-AppLog "SUCCESS: Verified LDAP RootDSE connection to domain '$($script:targetDomain)' via DC '$($script:targetServer)'." "SUCCESS"
            $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
            $dlg.Close()
        }
        catch {
            $rawMsg = $_.Exception.Message
            $cleanMsg = if ($rawMsg -match 'member\s+"Dispose":\s*"([^"]+)"') { $matches[1] } else { $rawMsg }
            $lblDlgStatus.Text = "Verification failed: $cleanMsg"
            $lblDlgStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
            Write-AppLog "Domain connection verification failed: $cleanMsg" "ERROR"
        }
    })

    [void]$dlg.ShowDialog($form)
}

# -----------------------------------------------------------------------------
# RELEASE NOTES & CHANGELOG DIALOG
# -----------------------------------------------------------------------------
function Show-ChangelogWindow {
    param(
        [string]$ChangelogText = "",
        [string]$VersionTag = ""
    )
    if ([string]::IsNullOrWhiteSpace($VersionTag)) {
        $VersionTag = "v$($script:AppVersion)"
    }
    $isDark = if ($null -ne $script:isDark) { [bool]$script:isDark } else { $true }

    $dlgNotes = New-Object System.Windows.Forms.Form
    $dlgNotes.Text = "Security Incident Automator - Release Notes ($VersionTag)"
    $dlgNotes.Size = New-Object System.Drawing.Size(640, 500)
    $dlgNotes.StartPosition = "CenterParent"
    $dlgNotes.FormBorderStyle = "FixedDialog"
    $dlgNotes.MaximizeBox = $false
    $dlgNotes.MinimizeBox = $false
    $dlgNotes.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(248, 250, 252) }

    $dlgHeader = New-Object System.Windows.Forms.Panel
    $dlgHeader.Size = New-Object System.Drawing.Size(640, 50)
    $dlgHeader.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $dlgNotes.Controls.Add($dlgHeader)

    $dlgTitle = New-Object System.Windows.Forms.Label
    $dlgTitle.Text = "Version Changelog & Release Notes ($VersionTag)"
    $dlgTitle.Font = New-Object System.Drawing.Font("Segoe UI", 10.5, [System.Drawing.FontStyle]::Bold)
    $dlgTitle.ForeColor = [System.Drawing.Color]::White
    $dlgTitle.Location = New-Object System.Drawing.Point(15, 13)
    $dlgTitle.AutoSize = $true
    $dlgHeader.Controls.Add($dlgTitle)

    $resolvedNotes = $ChangelogText
    if ([string]::IsNullOrWhiteSpace($resolvedNotes)) {
        try {
            $baseDir = if (-not [string]::IsNullOrWhiteSpace($script:MainScriptPath)) {
                Split-Path -Parent $script:MainScriptPath
            } else {
                Split-Path -Parent ((Get-Process -Id $PID).Path)
            }
            $localChangelog = Join-Path $baseDir "CHANGELOG.md"
            if (Test-Path -LiteralPath $localChangelog) {
                $resolvedNotes = (Get-Content -LiteralPath $localChangelog -Raw -ErrorAction Stop) -replace "`r?`n", "`r`n"
            }
        } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($resolvedNotes)) {
        $resolvedNotes =
            "SECURITY INCIDENT RESPONSE AUTOMATOR - CHANGELOG`r`n" +
            "===========================================================`r`n" +
            "Current Installed Release: v$($script:AppVersion)`r`n`r`n" +
            "## [1.1.52] - 2026-11-12`r`n" +
            "### Changed`r`n" +
            "  * Testing Update Feature`r`n`r`n" +
            "## [1.1.51] - 2026-11-12`r`n" +
            "### Added & Fixed`r`n" +
            "  * Added GitHub Check for Updates & Self-Updater dialog supporting both Launch-IncidentAutomator.bat (.ps1) and compiled IncidentResponse.exe hot-swap restarts.`r`n" +
            "  * Added dedicated View Changelog release notes dialog with Light / Dark mode support.`r`n" +
            "  * Colorized update status output lines (green when up to date, red when an update is available) and fixed WinForms mnemonic rendering on 'Update & Restart'.`r`n" +
            "  * Fixed Microsoft Graph silent CurrentUser MSAL session restoration for delegated operators on fresh workstations.`r`n`r`n" +
            "## [1.1.5] - 2026-11-05`r`n" +
            "  * Dynamic Multi-Domain Auto-Discovery Engine (Get-DiscoveredLocalDomainSafe).`r`n" +
            "  * Unified Light Mode & Dark Mode Dynamic Theme Engine.`r`n" +
            "  * Stateful Event Catalog & Query Persistence on Tab 4."
    }

    $txtNotes = New-Object System.Windows.Forms.TextBox
    $txtNotes.Multiline = $true
    $txtNotes.ReadOnly = $true
    $txtNotes.ScrollBars = "Vertical"
    $txtNotes.Location = New-Object System.Drawing.Point(15, 62)
    $txtNotes.Size = New-Object System.Drawing.Size(595, 340)
    $txtNotes.Font = New-Object System.Drawing.Font("Consolas", 9)
    $txtNotes.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(2, 6, 23) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $txtNotes.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(226, 232, 240) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $txtNotes.Text = $resolvedNotes
    $txtNotes.SelectionStart = 0
    $txtNotes.SelectionLength = 0
    $dlgNotes.Controls.Add($txtNotes)

    $btnCloseNotes = New-Object System.Windows.Forms.Button
    $btnCloseNotes.Text = "Close"
    $btnCloseNotes.UseMnemonic = $false
    $btnCloseNotes.Location = New-Object System.Drawing.Point(490, 412)
    $btnCloseNotes.Size = New-Object System.Drawing.Size(120, 32)
    $btnCloseNotes.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnCloseNotes.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(226, 232, 240) }
    $btnCloseNotes.ForeColor = if ($isDark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $btnCloseNotes.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCloseNotes.Add_Click({ $dlgNotes.Close() })
    $dlgNotes.Controls.Add($btnCloseNotes)
    $dlgNotes.CancelButton = $btnCloseNotes

    [void]$dlgNotes.ShowDialog($form)
}

# -----------------------------------------------------------------------------
# CHECK FOR UPDATES DIALOG (GitHub Release Check, Colorized Log, & Self-Updater)
# -----------------------------------------------------------------------------
function Show-UpdateCheckWindow {
    $isDark = if ($null -ne $script:isDark) { [bool]$script:isDark } else { $true }

    $bgLog    = if ($isDark) { [System.Drawing.Color]::FromArgb(2, 6, 23) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $fgLog    = if ($isDark) { [System.Drawing.Color]::FromArgb(226, 232, 240) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $fgGreen  = if ($isDark) { [System.Drawing.Color]::FromArgb(74, 222, 128) } else { [System.Drawing.Color]::FromArgb(22, 163, 74) }
    $fgRed    = if ($isDark) { [System.Drawing.Color]::FromArgb(248, 113, 113) } else { [System.Drawing.Color]::FromArgb(220, 38, 38) }

    $dlgUpd = New-Object System.Windows.Forms.Form
    $dlgUpd.Text = "Security Incident Automator - Check for Updates"
    $dlgUpd.Size = New-Object System.Drawing.Size(660, 504)
    $dlgUpd.StartPosition = "CenterParent"
    $dlgUpd.FormBorderStyle = "FixedDialog"
    $dlgUpd.MaximizeBox = $false
    $dlgUpd.MinimizeBox = $false
    $dlgUpd.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(248, 250, 252) }

    # Top Section GroupBox Container
    $grpTop = New-Object System.Windows.Forms.GroupBox
    $grpTop.Location = New-Object System.Drawing.Point(15, 10)
    $grpTop.Size = New-Object System.Drawing.Size(615, 122)
    $grpTop.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $grpTop.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(248, 250, 252) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $dlgUpd.Controls.Add($grpTop)

    $lblAppVer = New-Object System.Windows.Forms.Label
    $lblAppVer.Text = "Application Version: v$($script:AppVersion) (Installed)"
    $lblAppVer.Font = New-Object System.Drawing.Font("Segoe UI", 11, [System.Drawing.FontStyle]::Bold)
    $lblAppVer.Location = New-Object System.Drawing.Point(15, 14)
    $lblAppVer.Size = New-Object System.Drawing.Size(585, 24)
    $lblAppVer.ForeColor = if ($isDark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $grpTop.Controls.Add($lblAppVer)

    $lblSubDesc = New-Object System.Windows.Forms.Label
    $lblSubDesc.Text = "Checks GitHub for newer releases. When an update is confirmed, it downloads the latest release, hot-swaps the running script or executable, and restarts automatically."
    $lblSubDesc.Font = New-Object System.Drawing.Font("Segoe UI", 8.25)
    $lblSubDesc.Location = New-Object System.Drawing.Point(15, 38)
    $lblSubDesc.Size = New-Object System.Drawing.Size(585, 34)
    $lblSubDesc.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(148, 163, 184) } else { [System.Drawing.Color]::FromArgb(100, 116, 139) }
    $grpTop.Controls.Add($lblSubDesc)

    $lblRepo = New-Object System.Windows.Forms.Label
    $lblRepo.Text = "GitHub Repository (owner/repo):"
    $lblRepo.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $lblRepo.Location = New-Object System.Drawing.Point(15, 80)
    $lblRepo.Size = New-Object System.Drawing.Size(202, 22)
    $lblRepo.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(226, 232, 240) } else { [System.Drawing.Color]::FromArgb(51, 65, 85) }
    $grpTop.Controls.Add($lblRepo)

    $txtRepo = New-Object System.Windows.Forms.TextBox
    $txtRepo.Location = New-Object System.Drawing.Point(218, 78)
    $txtRepo.Size = New-Object System.Drawing.Size(246, 24)
    $txtRepo.Font = New-Object System.Drawing.Font("Segoe UI", 8.75)
    $txtRepo.Text = "mkstewart88/Security-Incident-Helper"
    $txtRepo.BackColor = $bgLog
    $txtRepo.ForeColor = $fgLog
    $grpTop.Controls.Add($txtRepo)

    $btnCheckNow = New-Object System.Windows.Forms.Button
    $btnCheckNow.Text = "Check for Updates"
    $btnCheckNow.UseMnemonic = $false
    $btnCheckNow.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnCheckNow.Location = New-Object System.Drawing.Point(472, 76)
    $btnCheckNow.Size = New-Object System.Drawing.Size(128, 28)
    $btnCheckNow.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
    $btnCheckNow.ForeColor = if ($isDark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $btnCheckNow.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $grpTop.Controls.Add($btnCheckNow)

    # Middle Output RichTextBox (supports per-line green/red status coloring and clickable URLs)
    $txtLogUpd = New-Object System.Windows.Forms.RichTextBox
    $txtLogUpd.ReadOnly = $true
    $txtLogUpd.ScrollBars = [System.Windows.Forms.RichTextBoxScrollBars]::Vertical
    $txtLogUpd.DetectUrls = $true
    $txtLogUpd.BorderStyle = [System.Windows.Forms.BorderStyle]::Fixed3D
    $txtLogUpd.Location = New-Object System.Drawing.Point(15, 140)
    $txtLogUpd.Size = New-Object System.Drawing.Size(615, 218)
    $txtLogUpd.Font = New-Object System.Drawing.Font("Consolas", 8.75)
    $txtLogUpd.BackColor = $bgLog
    $txtLogUpd.ForeColor = $fgLog
    $txtLogUpd.Add_LinkClicked({
        param($sender, $e)
        if ($e -and (-not [string]::IsNullOrWhiteSpace($e.LinkText))) {
            try { Start-Process $e.LinkText } catch {}
        }
    })
    $dlgUpd.Controls.Add($txtLogUpd)

    # Bottom Progress Bar
    $prgUpd = New-Object System.Windows.Forms.ProgressBar
    $prgUpd.Location = New-Object System.Drawing.Point(15, 366)
    $prgUpd.Size = New-Object System.Drawing.Size(615, 16)
    $prgUpd.Minimum = 0
    $prgUpd.Maximum = 100
    $prgUpd.Value = 0
    $dlgUpd.Controls.Add($prgUpd)

    # Bottom Action Buttons
    $btnViewChangelog = New-Object System.Windows.Forms.Button
    $btnViewChangelog.Text = "View Changelog"
    $btnViewChangelog.UseMnemonic = $false
    $btnViewChangelog.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnViewChangelog.Location = New-Object System.Drawing.Point(15, 398)
    $btnViewChangelog.Size = New-Object System.Drawing.Size(145, 36)
    $btnViewChangelog.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
    $btnViewChangelog.ForeColor = if ($isDark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $btnViewChangelog.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $dlgUpd.Controls.Add($btnViewChangelog)

    $btnUpdateRestart = New-Object System.Windows.Forms.Button
    $btnUpdateRestart.UseMnemonic = $false
    $btnUpdateRestart.Text = "Update & Restart"
    $btnUpdateRestart.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnUpdateRestart.Location = New-Object System.Drawing.Point(325, 398)
    $btnUpdateRestart.Size = New-Object System.Drawing.Size(160, 36)
    $btnUpdateRestart.Enabled = $false
    $btnUpdateRestart.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(203, 213, 225) }
    $btnUpdateRestart.ForeColor = [System.Drawing.Color]::White
    $btnUpdateRestart.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $dlgUpd.Controls.Add($btnUpdateRestart)

    $btnCloseUpd = New-Object System.Windows.Forms.Button
    $btnCloseUpd.Text = "Close"
    $btnCloseUpd.UseMnemonic = $false
    $btnCloseUpd.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $btnCloseUpd.Location = New-Object System.Drawing.Point(500, 398)
    $btnCloseUpd.Size = New-Object System.Drawing.Size(130, 36)
    $btnCloseUpd.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
    $btnCloseUpd.ForeColor = if ($isDark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $btnCloseUpd.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCloseUpd.Add_Click({ $dlgUpd.Close() })
    $dlgUpd.Controls.Add($btnCloseUpd)
    $dlgUpd.CancelButton = $btnCloseUpd

    $updState = @{
        ReleaseData        = $null
        ConfirmedUpdate    = $false
        LatestTag          = "v$($script:AppVersion)"
        RepoTarget         = $txtRepo.Text.Trim()
        RawFallbackNotes   = ""
        UseRawMainFallback = $false
        FallbackRef        = "main"
    }

    $appendUpdLine = {
        param(
            [string]$Text,
            [System.Drawing.Color]$Color
        )
        if ($null -eq $Color) { $Color = $fgLog }
        $txtLogUpd.SelectionStart = $txtLogUpd.TextLength
        $txtLogUpd.SelectionLength = 0
        $txtLogUpd.SelectionColor = $Color
        $txtLogUpd.AppendText("$Text`r`n")
        $txtLogUpd.SelectionColor = $fgLog
    }

    $decodeWebContent = {
        param($Resp)
        if ($null -eq $Resp -or $null -eq $Resp.Content) { return "" }
        $txt = if ($Resp.Content -is [byte[]]) {
            [System.Text.Encoding]::UTF8.GetString($Resp.Content)
        } else {
            [string]$Resp.Content
        }
        return $txt.TrimStart([char]0xFEFF)
    }

    $runCheckLogic = {
        $repoTarget = $txtRepo.Text.Trim()
        if ($repoTarget -match '^(?:https?://)?(?:www\.)?github\.com/([^/\s]+/[^/\s]+?)(?:\.git)?/?$') {
            $repoTarget = $Matches[1]
            $txtRepo.Text = $repoTarget
        }
        $updState.RepoTarget = $repoTarget
        $updState.ReleaseData = $null
        $updState.ConfirmedUpdate = $false
        $updState.RawFallbackNotes = ""
        $updState.UseRawMainFallback = $false
        $txtLogUpd.Clear()

        if ([string]::IsNullOrWhiteSpace($repoTarget) -or (-not ($repoTarget -match '^[^/\s]+/[^/\s]+$'))) {
            & $appendUpdLine "[ERROR] Please enter a valid GitHub repository in owner/repo format." $fgRed
            return
        }

        $btnUpdateRestart.Enabled = $false
        $btnUpdateRestart.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(203, 213, 225) }
        $prgUpd.Value = 15

        $instVer = [string]$script:AppVersion
        & $appendUpdLine "[CHECK] Initializing GitHub connection with TLS 1.2 / TLS 1.3..." $fgLog
        & $appendUpdLine "[REPOSITORY] Target: https://github.com/$repoTarget" $fgLog
        & $appendUpdLine "[STATUS] Installed Version: v$instVer" $fgLog
        $dlgUpd.Refresh()

        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        $apiUrl = "https://api.github.com/repos/$repoTarget/releases/latest"
        $updState.FallbackRef = "main"
        $headers = @{
            'User-Agent'    = 'SecurityIncidentAutomator-App'
            'Accept'        = 'application/vnd.github+json'
            'Cache-Control' = 'no-cache'
        }

        try {
            $prgUpd.Value = 45
            $latestTag = ""
            try {
                $relObj = Invoke-RestMethod -Uri $apiUrl -Headers $headers -TimeoutSec 10 -ErrorAction Stop
                $updState.ReleaseData = $relObj
                $latestTag = if ($relObj.tag_name) { [string]$relObj.tag_name } else { "v$instVer" }
            } catch {
                # If no formal GitHub Release has been published yet (HTTP 404), resolve latest commit on main
                # and query GitHub API Contents (raw) first to bypass raw.githubusercontent.com 5-minute CDN cache.
                $isNotFound = $false
                try {
                    if ($_.Exception.Response -and ([int]$_.Exception.Response.StatusCode -eq 404)) {
                        $isNotFound = $true
                    }
                } catch {}
                if (-not $isNotFound -and ($_.Exception.Message -match '404')) { $isNotFound = $true }
                if (-not $isNotFound) { throw }

                $fallbackRef = "main"
                try {
                    $commitObj = Invoke-RestMethod -Uri "https://api.github.com/repos/$repoTarget/commits/main" -Headers $headers -TimeoutSec 10 -ErrorAction Stop
                    if ($commitObj -and $commitObj.sha) {
                        $fallbackRef = [string]$commitObj.sha
                    }
                } catch {}
                $updState.FallbackRef = $fallbackRef

                $rawApiHeaders = @{
                    'User-Agent'    = 'SecurityIncidentAutomator-App'
                    'Accept'        = 'application/vnd.github.raw+json'
                    'Cache-Control' = 'no-cache'
                }

                $cleanRaw = ""
                try {
                    $apiVerResp = Invoke-WebRequest -Uri "https://api.github.com/repos/$repoTarget/contents/VERSION?ref=$fallbackRef" -Headers $rawApiHeaders -UseBasicParsing -TimeoutSec 10 -ErrorAction Stop
                    $cleanRaw = (& $decodeWebContent $apiVerResp).Trim()
                } catch {
                    $rawVerUrl = "https://raw.githubusercontent.com/$repoTarget/$fallbackRef/VERSION"
                    $rawVerResp = Invoke-WebRequest -Uri $rawVerUrl -Headers $headers -UseBasicParsing -TimeoutSec 10 -ErrorAction Stop
                    $cleanRaw = (& $decodeWebContent $rawVerResp).Trim()
                }

                if ([string]::IsNullOrWhiteSpace($cleanRaw)) { throw "Empty VERSION response from GitHub." }
                $latestTag = if ($cleanRaw.StartsWith('v', [StringComparison]::OrdinalIgnoreCase)) { $cleanRaw } else { "v$cleanRaw" }
                $updState.UseRawMainFallback = $true
                try {
                    $rawChgResp = Invoke-WebRequest -Uri "https://api.github.com/repos/$repoTarget/contents/CHANGELOG.md?ref=$fallbackRef" -Headers $rawApiHeaders -UseBasicParsing -TimeoutSec 8 -ErrorAction Stop
                    if ($rawChgResp -and $rawChgResp.Content) {
                        $updState.RawFallbackNotes = ((& $decodeWebContent $rawChgResp) -replace "`r?`n", "`r`n")
                    }
                } catch {
                    try {
                        $rawChgResp = Invoke-WebRequest -Uri "https://raw.githubusercontent.com/$repoTarget/$fallbackRef/CHANGELOG.md" -Headers $headers -UseBasicParsing -TimeoutSec 8 -ErrorAction SilentlyContinue
                        if ($rawChgResp -and $rawChgResp.Content) { $updState.RawFallbackNotes = ((& $decodeWebContent $rawChgResp) -replace "`r?`n", "`r`n") }
                    } catch {}
                }
            }

            $updState.LatestTag = $latestTag
            $cleanLat = ($latestTag -replace '[^0-9\.]', '').Trim('.')
            $cleanInst = ($instVer -replace '[^0-9\.]', '').Trim('.')

            $prgUpd.Value = 75
            & $appendUpdLine "[STATUS] GitHub Latest Version: $latestTag" $fgLog

            $isNewer = $false
            try {
                $vI = [version]$cleanInst
                $vL = [version]$cleanLat
                if ($vL -gt $vI) { $isNewer = $true }
            } catch {
                if (-not [string]::Equals($cleanInst, $cleanLat, [StringComparison]::OrdinalIgnoreCase)) {
                    $isNewer = $true
                }
            }

            $prgUpd.Value = 100
            & $appendUpdLine "" $fgLog
            if ($isNewer) {
                $updState.ConfirmedUpdate = $true
                & $appendUpdLine "[UPDATE AVAILABLE] You're not running the latest version (Latest: $latestTag)." $fgRed
                & $appendUpdLine "Click 'Update & Restart' to install or 'View Changelog' to review changes." $fgLog
                $btnUpdateRestart.Enabled = $true
                $btnUpdateRestart.BackColor = [System.Drawing.Color]::FromArgb(37, 99, 235)
                $btnUpdateRestart.ForeColor = [System.Drawing.Color]::White
            } else {
                $updState.ConfirmedUpdate = $false
                & $appendUpdLine "[UP TO DATE] You're running the latest version of Security Incident Automator." $fgGreen
                & $appendUpdLine "Click 'View Changelog' to review changes." $fgLog
            }
        } catch {
            $prgUpd.Value = 100
            & $appendUpdLine "" $fgLog
            & $appendUpdLine "[ERROR] Failed to check GitHub for updates: $($_.Exception.Message)" $fgRed
            & $appendUpdLine "Verify internet connectivity and repository path, then try again." $fgLog
        }
    }

    $btnCheckNow.Add_Click({
        & $runCheckLogic
    })

    $btnViewChangelog.Add_Click({
        $notes = if ($updState.ReleaseData -and $updState.ReleaseData.body) {
            ([string]$updState.ReleaseData.body) -replace "`r?`n", "`r`n"
        } elseif (-not [string]::IsNullOrWhiteSpace($updState.RawFallbackNotes)) {
            $updState.RawFallbackNotes
        } else {
            ""
        }
        $tag = if (-not [string]::IsNullOrWhiteSpace($updState.LatestTag)) {
            $updState.LatestTag
        } else {
            "v$($script:AppVersion)"
        }
        Show-ChangelogWindow -ChangelogText $notes -VersionTag $tag
    })

    $btnUpdateRestart.Add_Click({
        if (-not $updState.ConfirmedUpdate) { return }

        $btnUpdateRestart.Enabled = $false
        $btnCheckNow.Enabled = $false
        & $appendUpdLine "" $fgLog
        & $appendUpdLine "[DOWNLOADING] Fetching latest release from GitHub..." $fgLog
        $prgUpd.Value = 25
        $dlgUpd.Refresh()

        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
            $procPath = (Get-Process -Id $PID).Path
            $isCompiledExe = (-not [string]::IsNullOrWhiteSpace($procPath)) -and (-not ($procPath -match 'powershell(\.exe)?$|pwsh(\.exe)?$'))
            $repoTarget = $updState.RepoTarget
            $refName = if ($updState.UseRawMainFallback -or [string]::IsNullOrWhiteSpace($updState.LatestTag)) {
                if (-not [string]::IsNullOrWhiteSpace($updState.FallbackRef)) { $updState.FallbackRef } else { "main" }
            } else {
                $updState.LatestTag
            }

            $stageDir = Join-Path $env:TEMP ("IRAutomatorUpdate_" + [Guid]::NewGuid().ToString("N").Substring(0, 8))
            New-Item -Path $stageDir -ItemType Directory -Force | Out-Null

            if ($isCompiledExe) {
                $exeAsset = $null
                if ($updState.ReleaseData -and $updState.ReleaseData.assets) {
                    $exeAsset = $updState.ReleaseData.assets | Where-Object { $_.name -match '\.exe$' } | Select-Object -First 1
                }
                if (-not $exeAsset -or [string]::IsNullOrWhiteSpace($exeAsset.browser_download_url)) {
                    throw "No compiled .exe asset found on GitHub release '$refName'. Attach IncidentResponse.exe to a GitHub Release, or run via Launch-IncidentAutomator.bat to auto-update directly from main."
                }

                $stagedExe = "$procPath.new"
                Invoke-WebRequest -Uri $exeAsset.browser_download_url -OutFile $stagedExe -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop
                $prgUpd.Value = 75
                $dlgUpd.Refresh()

                $exeBytes = [System.IO.File]::ReadAllBytes($stagedExe)
                if ($exeBytes.Length -lt 10240 -or $exeBytes[0] -ne 0x4D -or $exeBytes[1] -ne 0x5A) {
                    Remove-Item -LiteralPath $stagedExe -Force -ErrorAction SilentlyContinue
                    throw "Downloaded executable failed PE header validation."
                }

                & $appendUpdLine "[HOT-SWAP] Applying executable update and restarting application..." $fgLog
                $prgUpd.Value = 95
                $dlgUpd.Refresh()

                $safeStagedExe = $stagedExe.Replace("'", "''")
                $safeProcPath  = $procPath.Replace("'", "''")
                $safeStageDir  = $stageDir.Replace("'", "''")
                $swapScript = @"
`$parentPid = $PID
`$sw = [System.Diagnostics.Stopwatch]::StartNew()
while (`$sw.Elapsed.TotalSeconds -lt 20) {
    if (-not (Get-Process -Id `$parentPid -ErrorAction SilentlyContinue)) { break }
    Start-Sleep -Milliseconds 250
}
Start-Sleep -Milliseconds 500
Move-Item -LiteralPath '$safeStagedExe' -Destination '$safeProcPath' -Force
Start-Process -FilePath '$safeProcPath'
Remove-Item -LiteralPath '$safeStageDir' -Recurse -Force -ErrorAction SilentlyContinue
"@
            } else {
                $targetPs1 = $script:MainScriptPath
                if ([string]::IsNullOrWhiteSpace($targetPs1) -or (-not (Test-Path -LiteralPath $targetPs1))) {
                    throw "Unable to locate running script path for in-place update."
                }
                $targetDir = Split-Path -Parent $targetPs1

                $ps1Url = $null
                if ($updState.ReleaseData -and $updState.ReleaseData.assets) {
                    $ps1Asset = $updState.ReleaseData.assets | Where-Object { $_.name -eq 'IncidentResponse-Automator.ps1' } | Select-Object -First 1
                    if ($ps1Asset) { $ps1Url = [string]$ps1Asset.browser_download_url }
                }
                if ([string]::IsNullOrWhiteSpace($ps1Url)) {
                    $ps1Url = "https://raw.githubusercontent.com/$repoTarget/$refName/IncidentResponse-Automator.ps1"
                }

                $stagedPs1 = Join-Path $stageDir "IncidentResponse-Automator.ps1"
                Invoke-WebRequest -Uri $ps1Url -OutFile $stagedPs1 -UseBasicParsing -TimeoutSec 45 -ErrorAction Stop
                $prgUpd.Value = 65
                $dlgUpd.Refresh()

                $tokens = $null
                $parseErrs = $null
                [void][System.Management.Automation.Language.Parser]::ParseFile($stagedPs1, [ref]$tokens, [ref]$parseErrs)
                if ($parseErrs -and $parseErrs.Count -gt 0) {
                    throw "Downloaded script failed PowerShell syntax validation ($($parseErrs[0].Message)). Update aborted."
                }

                foreach ($extraFile in @('VERSION', 'CHANGELOG.md', 'Launch-IncidentAutomator.bat', 'Compile-To-EXE.cmd')) {
                    try {
                        $extraUrl = "https://raw.githubusercontent.com/$repoTarget/$refName/$extraFile"
                        $extraDest = Join-Path $stageDir $extraFile
                        Invoke-WebRequest -Uri $extraUrl -OutFile $extraDest -UseBasicParsing -TimeoutSec 15 -ErrorAction Stop
                    } catch {}
                }

                & $appendUpdLine "[HOT-SWAP] Updating script files and restarting console..." $fgLog
                $prgUpd.Value = 95
                $dlgUpd.Refresh()

                $safeStageDir  = $stageDir.Replace("'", "''")
                $safeTargetDir = $targetDir.Replace("'", "''")
                $safeTargetPs1 = $targetPs1.Replace("'", "''")
                $batPath = Join-Path $targetDir "Launch-IncidentAutomator.bat"
                $relaunchCmd = if (Test-Path -LiteralPath $batPath) {
                    $safeBatPath = $batPath.Replace("'", "''")
                    "Start-Process -FilePath '$safeBatPath' -WorkingDirectory '$safeTargetDir'"
                } else {
                    "Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoLogo','-NoProfile','-ExecutionPolicy','Bypass','-STA','-File','$safeTargetPs1' -WorkingDirectory '$safeTargetDir'"
                }

                $swapScript = @"
`$parentPid = $PID
`$sw = [System.Diagnostics.Stopwatch]::StartNew()
while (`$sw.Elapsed.TotalSeconds -lt 20) {
    if (-not (Get-Process -Id `$parentPid -ErrorAction SilentlyContinue)) { break }
    Start-Sleep -Milliseconds 250
}
Start-Sleep -Milliseconds 400
Copy-Item -Path '$safeStageDir\*' -Destination '$safeTargetDir' -Force
Remove-Item -LiteralPath '$safeStageDir' -Recurse -Force -ErrorAction SilentlyContinue
$relaunchCmd
"@
            }

            $encCmd = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($swapScript))
            Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -EncodedCommand $encCmd" -WindowStyle Hidden

            $prgUpd.Value = 100
            $dlgUpd.Close()
            $form.Close()
        } catch {
            $btnCheckNow.Enabled = $true
            $btnUpdateRestart.Enabled = $updState.ConfirmedUpdate
            & $appendUpdLine "[ERROR] Update failed: $($_.Exception.Message)" $fgRed
            [System.Windows.Forms.MessageBox]::Show($dlgUpd, "Update failed: $($_.Exception.Message)", "Update Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    })

    $dlgUpd.Add_Shown({
        & $runCheckLogic
    })

    [void]$dlgUpd.ShowDialog($form)
}

$btnSwitchDomain.Add_Click({
    Show-DomainSwitcher
})

$script:currentUser = $null
$script:matchedUsers = @()

# Press Enter in search box triggers search
$txtSearch.Add_KeyDown({
    if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) {
        $btnLookup.PerformClick()
        $_.SuppressKeyPress = $true
    }
})

# Search Handler (Minimum 3 chars, Active Directory ANR + UPN + Mail + ProxyAddresses matching)
$btnLookup.Add_Click({
    $query = $txtSearch.Text.Trim()
    if ($query.Length -lt 3) {
        $lblSearchStatus.Text = "Please enter at least 3 characters to search Active Directory."
        $lblSearchStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        return
    }

    Write-AppLog "Searching Active Directory for '$query' (matching ANR, sAMAccountName, UPN, mail, and proxyAddresses)..." "INFO"
    $lstResults.Items.Clear()
    $script:currentUser = $null
    $script:matchedUsers = @()
    $chkVerified.Checked = $false
    $chkVerified.Enabled = $false
    $btnRefreshUserSessions.Enabled = $false
    $pnlResetPass.Visible = $false

    # Reset Identity Fields safely
    $lblIdName.Text = "Name: (Searching...)"
    $lblIdDept.Text = "UPN: --  |  Mail: --  |  sAMAccountName: --  |  Department: --"
    $lblCardPassVal.Text = "--"
    $lblCard365Val.Text = "--"
    $lblCardGoogleVal.Text = "--"
    $lblCardAcctVal.Text = "--"
    if (Get-Command Clear-ForwardingRulesResults -ErrorAction SilentlyContinue) { Clear-ForwardingRulesResults }
    if (Get-Command Clear-SecurityEventsResults -ErrorAction SilentlyContinue) { Clear-SecurityEventsResults }

    try {
        $safeChars = @()
        foreach ($ch in $query.ToCharArray()) {
            if ([char]::IsLetterOrDigit($ch) -or $ch -eq ' ' -or $ch -eq '.' -or $ch -eq '-' -or $ch -eq '_' -or $ch -eq '@') {
                $safeChars += $ch
            }
        }
        $safeQuery = (-join $safeChars).Trim()

        if ($safeQuery.Length -lt 2) {
            $lblSearchStatus.Text = "Please enter at least 3 valid search characters."
            $lblSearchStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
            return
        }

        $words = @($safeQuery.Split(" ", [System.StringSplitOptions]::RemoveEmptyEntries))
        $subFilters = @()

        $subFilters += "(anr=$safeQuery*)"
        $subFilters += "(sAMAccountName=$safeQuery*)"
        $subFilters += "(userPrincipalName=$safeQuery*)"
        $subFilters += "(mail=$safeQuery*)"
        $subFilters += "(proxyAddresses=smtp:$safeQuery*)"

        if ($words.Count -gt 1) {
            $wordAnds = ""
            foreach ($w in $words) {
                if ($w.Length -gt 0) {
                    $wordAnds += "(|(anr=$w*)(sAMAccountName=*$w*)(userPrincipalName=*$w*)(mail=*$w*)(displayName=*$w*)(givenName=*$w*)(sn=*$w*))"
                }
            }
            $subFilters += "(&$wordAnds)"
        } else {
            $subFilters += "(displayName=*$safeQuery*)"
            $subFilters += "(sAMAccountName=*$safeQuery*)"
            $subFilters += "(mail=*$safeQuery*)"
            $subFilters += "(userPrincipalName=*$safeQuery*)"
            $subFilters += "(proxyAddresses=smtp:*$safeQuery*)"
        }

        $ldapFilter = "(&(objectCategory=person)(objectClass=user)(|" + ($subFilters -join "") + "))"

        $adUsers = @(Query-ADUsersSafe -LdapFilter $ldapFilter -Server $script:targetServer -Cred $script:adCredential)

        if (-not $adUsers -or $adUsers.Count -eq 0) {
            $term = if ($words.Count -gt 0) { $words[0] } else { $safeQuery }
            $fallbackFilter = "(&(objectCategory=person)(objectClass=user)(|(sAMAccountName=*$term*)(userPrincipalName=*$term*)(mail=*$term*)(displayName=*$term*)(name=*$term*)))"
            $adUsers = @(Query-ADUsersSafe -LdapFilter $fallbackFilter -Server $script:targetServer -Cred $script:adCredential)
        }

        if (-not $adUsers -or $adUsers.Count -eq 0) {
            $lblSearchStatus.Text = "0 users found in Active Directory matching '$query'."
            $lblSearchStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
            $lblIdName.Text = "Name: (No user found matching '$query')"
            Write-AppLog "No users found in Active Directory matching '$query'." "WARN"
            return
        }

        $script:matchedUsers = $adUsers
        $lblSearchStatus.Text = "Found $($adUsers.Count) user(s). Click a user below to select identity:"
        $lblSearchStatus.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)

        foreach ($u in $adUsers) {
            $dispName = if ($u.DisplayName) { $u.DisplayName } elseif ($u.Name) { $u.Name } else { "$($u.GivenName) $($u.Surname)" }
            $dept = if ($u.Department) { $u.Department } else { "No Dept" }
            $stat = if (-not $u.Enabled) { "DISABLED" } elseif ($u.LockedOut) { "LOCKED" } else { "ACTIVE" }
            $upn = if ($u.UserPrincipalName) { $u.UserPrincipalName } else { $u.Mail }
            $mailTag = if ($u.Mail -and (-not [string]::Equals($upn, $u.Mail, [StringComparison]::OrdinalIgnoreCase))) { "  |  Mail: $($u.Mail)" } else { "" }
            $line = "$dispName  |  UPN: $upn$mailTag  |  sAM: $($u.SamAccountName)  |  [$stat]  |  $dept"
            [void]$lstResults.Items.Add($line)
        }

        Write-AppLog "Found $($adUsers.Count) user(s) matching '$query'." "INFO"
        $lstResults.SelectedIndex = 0
    }
    catch {
        $lblSearchStatus.Text = "AD Search Error: $($_.Exception.Message)"
        $lblSearchStatus.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        $lblIdName.Text = "Name: (Query error)"
        Write-AppLog "Active Directory query error: $($_.Exception.Message). If not domain joined, click 'Switch Domain / DC'." "ERROR"
    }
})

function Update-SelectedUserSessionBoxes {
    if ($null -eq $script:currentUser) { return }
    $u = $script:currentUser

    $lblCard365Val.Text = "Checking 365..."
    $lblCard365Sub.Text = "Querying Graph..."
    $lblCardGoogleVal.Text = "Checking GAM..."
    $lblCardGoogleSub.Text = "Querying GAM7..."
    $form.Refresh()

    $telemetry = Get-UserActiveSessionTelemetry -UserObj $u
    if ($telemetry.GraphMatch) {
        $script:currentUser.GraphTargetId = $telemetry.GraphMatch
    }
    if ($telemetry.GamMatch) {
        $script:currentUser.GamTargetId = $telemetry.GamMatch
    }

    $lblCard365Val.Text = $telemetry.GraphStatus
    $lblCard365Sub.Text = $telemetry.GraphSub

    $lblCardGoogleVal.Text = $telemetry.GamStatus
    $lblCardGoogleSub.Text = $telemetry.GamSub
}

$btnRefreshUserSessions.Add_Click({
    if ($null -eq $script:currentUser) { return }
    Write-AppLog "Refreshing cloud session & identity correlation status for '$($script:currentUser.DisplayName)'..." "INFO"
    Update-SelectedUserSessionBoxes
    Write-AppLog "Session status refreshed: 365=[$($lblCard365Val.Text) - $($lblCard365Sub.Text)] | Google=[$($lblCardGoogleVal.Text) - $($lblCardGoogleSub.Text)]" "INFO"
})

# Selection Handler for Search Results ListBox
$lstResults.Add_SelectedIndexChanged({
    if ($lstResults.SelectedIndex -lt 0 -or $lstResults.SelectedIndex -ge $script:matchedUsers.Count) {
        return
    }

    $selectedADUser = $script:matchedUsers[$lstResults.SelectedIndex]
    if ($null -eq $selectedADUser) { return }

    $dispName = if ($selectedADUser.DisplayName) { $selectedADUser.DisplayName } elseif ($selectedADUser.Name) { $selectedADUser.Name } else { "$($selectedADUser.GivenName) $($selectedADUser.Surname)" }
    $upn = if ($selectedADUser.UserPrincipalName) { $selectedADUser.UserPrincipalName } else { $selectedADUser.Mail }
    $mail = if ($selectedADUser.Mail) { $selectedADUser.Mail } else { $upn }
    $graphTarget = if ($selectedADUser.GraphTargetId) { $selectedADUser.GraphTargetId } else { $upn }
    $gamTarget = if ($selectedADUser.GamTargetId) { $selectedADUser.GamTargetId } else { $mail }
    $cloudCands = if ($selectedADUser.CloudCandidates) { @($selectedADUser.CloudCandidates) } else { @($upn, $mail) }

    $office = if ($selectedADUser.Office) { $selectedADUser.Office } else { "Main Office" }
    $pwdAge = if ($null -ne $selectedADUser.PasswordAge) { $selectedADUser.PasswordAge } else { "Unknown" }
    $pwdSetFmt = if ($selectedADUser.PasswordLastSetFormatted) { $selectedADUser.PasswordLastSetFormatted } elseif ($selectedADUser.PasswordLastSet) { [string]$selectedADUser.PasswordLastSet } else { "--" }
    $lastLogon = if ($selectedADUser.LastLogonDisplay) { $selectedADUser.LastLogonDisplay } else { "Unknown" }
    $acctExpDisp = if ($selectedADUser.AccountExpiresDisplay) { $selectedADUser.AccountExpiresDisplay } else { "Never Expires" }
    $logonWksDisp = if ($selectedADUser.LogonWorkstationsDisplay) { $selectedADUser.LogonWorkstationsDisplay } else { "All Workstations" }
    $isLocked = [bool]$selectedADUser.LockedOut

    # Query non-replicated lastLogon & lockoutTime across all Domain Controllers so 9-14 day lastLogonTimestamp lag never hides recent logons
    try {
        $multiDcLogon = Get-MultiDCUserNonReplicatedTelemetrySafe -SamAccountName ([string]$selectedADUser.SamAccountName) -Server $script:targetServer -Cred $script:adCredential
        if ($multiDcLogon -and $multiDcLogon.LatestLogonDisplay -and $multiDcLogon.LatestLogonDisplay -ne "Never / Unknown") {
            $lastLogon = [string]$multiDcLogon.LatestLogonDisplay
        }
        if ($multiDcLogon -and $multiDcLogon.IsLockedOutAnyDC) {
            $isLocked = $true
        }
    } catch {}

    $script:currentUser = @{
        SamAccountName           = $selectedADUser.SamAccountName
        UserPrincipalName        = $upn
        Mail                     = $mail
        GraphTargetId            = $graphTarget
        GamTargetId              = $gamTarget
        CloudCandidates          = $cloudCands
        DisplayName              = $dispName
        Title                    = if ($selectedADUser.Title) { $selectedADUser.Title } else { "Staff" }
        Department               = if ($selectedADUser.Department) { $selectedADUser.Department } else { "General" }
        Office                   = $office
        Enabled                  = [bool]$selectedADUser.Enabled
        LockedOut                = $isLocked
        PasswordLastSet          = $pwdSetFmt
        PasswordAge              = $pwdAge
        LastLogonDisplay         = $lastLogon
        AccountExpiresDisplay    = $acctExpDisp
        LogonWorkstationsDisplay = $logonWksDisp
    }

    $u = $script:currentUser
    $lblIdName.Text = "Name: $($u.DisplayName)  (sAMAccountName: $($u.SamAccountName))"
    $mailDisplay = if ($u.Mail -and (-not [string]::Equals($u.UserPrincipalName, $u.Mail, [StringComparison]::OrdinalIgnoreCase))) { "  |  Mail: $($u.Mail)" } else { "" }
    $lblIdDept.Text = "UPN: $($u.UserPrincipalName)$mailDisplay  |  Dept: $($u.Department)  |  Site: $($u.Office)"

    # Populate Security Intelligence & Active Session Metric Boxes
    $lblCardPassVal.Text = if ($u.PasswordLastSet -eq "Must Change at Logon") { "0 days (Expired)" } elseif ($u.PasswordAge -ne "Unknown") { "$($u.PasswordAge) days" } else { "Unknown" }
    $lblCardPassSub.Text = "Set: $($u.PasswordLastSet)"

    $lblCardAcctVal.Text = if (-not $u.Enabled) { "DISABLED" } elseif ($u.LockedOut) { "LOCKED OUT" } else { "ACTIVE" }
    $lblCardAcctSub.Text = "Logon: $($u.LastLogonDisplay)"
    $btnEmergencyLock.Text = if ($u.Enabled) { "4. Disable Account" } else { "4. Enable Account" }

    $chkVerified.Enabled = $true
    $chkVerified.Checked = $false
    $btnRefreshUserSessions.Enabled = $true
    $pnlResetPass.Visible = $false

    # Auto-clear previous user's Tab 3 (Forwarding Rules) and Tab 4 (Event Triage) results on user change
    if (Get-Command Clear-ForwardingRulesResults -ErrorAction SilentlyContinue) { Clear-ForwardingRulesResults }
    if (Get-Command Clear-SecurityEventsResults -ErrorAction SilentlyContinue) { Clear-SecurityEventsResults }

    if (Get-Command Update-ExtendedTabsUserHeader -ErrorAction SilentlyContinue) {
        Update-ExtendedTabsUserHeader
    }

    Update-SelectedUserSessionBoxes
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }

    Write-AppLog "Loaded user '$($u.DisplayName)' (AD UPN: $($u.UserPrincipalName) | Graph ID: $($u.GraphTargetId) | GAM ID: $($u.GamTargetId)). Check verification box to unlock actions." "INFO"
})

# Verification Checkbox Toggle
$chkVerified.Add_CheckedChanged({
    $isEnabled = $chkVerified.Checked -and ($null -ne $script:currentUser)
    $btnResetPass.Enabled = $isEnabled
    $btnRevoke365.Enabled = $isEnabled
    $btnRevokeGoogle.Enabled = $isEnabled
    $btnEmergencyLock.Enabled = $isEnabled
    $btnContainAll.Enabled = $isEnabled

    if ($btnBlockEntraSignIn) { $btnBlockEntraSignIn.Enabled = $isEnabled }
    if ($btnUnblockEntraSignIn) { $btnUnblockEntraSignIn.Enabled = $isEnabled }
    if ($btnSuspendGoogle) { $btnSuspendGoogle.Enabled = $isEnabled }
    if ($btnUnsuspendGoogle) { $btnUnsuspendGoogle.Enabled = $isEnabled }
    if ($btnWipeCloudMfa) { $btnWipeCloudMfa.Enabled = $isEnabled }
    if ($btnExpireAdNow) { $btnExpireAdNow.Enabled = $isEnabled }
    if ($btnRestoreAdRestrictions) { $btnRestoreAdRestrictions.Enabled = $isEnabled }
    if ($btnAuditForwardingRules) { $btnAuditForwardingRules.Enabled = $isEnabled }
    if ($btnPullSecurityEvents) { $btnPullSecurityEvents.Enabled = ($null -ne $script:currentUser) }
    if (Get-Command Update-RuleActionButtonsState -ErrorAction SilentlyContinue) { Update-RuleActionButtonsState }

    if (Get-Command Update-ExtendedTabsUserHeader -ErrorAction SilentlyContinue) {
        Update-ExtendedTabsUserHeader
    }

    if ($isEnabled) {
        Write-AppLog "Identity verified by admin for $($script:currentUser.UserPrincipalName). Primary & Extended Lockdown decks unlocked." "SUCCESS"
    } else {
        $pnlResetPass.Visible = $false
    }

    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

function Prompt-CheckDiagnosticsTab {
    param(
        [string]$ServiceName,
        [string]$Reason,
        [string]$SetupInstruction
    )
    $nl = [System.Environment]::NewLine
    $msg = "$ServiceName is not linked or verified on this workstation.$nl$nl" +
           "Status: $Reason$nl$nl" +
           "$SetupInstruction$nl$nl" +
           "Please check the second tab ('Health & Diagnostics') to link and verify your accounts.$nl$nl" +
           "Would you like to switch to the 'Health & Diagnostics' tab now?"
    $ans = [System.Windows.Forms.MessageBox]::Show(
        $form,
        $msg,
        "$ServiceName Account Not Linked - Check Tab 2 (Health & Diagnostics)",
        [System.Windows.Forms.MessageBoxButtons]::YesNo,
        [System.Windows.Forms.MessageBoxIcon]::Warning
    )
    if ($ans -eq [System.Windows.Forms.DialogResult]::Yes) {
        $tabControl.SelectedTab = $tabDiag
    }
}

function Show-PasswordResetCustomDialog {
    if ($null -eq $script:currentUser) { return }
    $u = $script:currentUser

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = "Reset Active Directory Password - $($u.DisplayName)"
    $dlg.Size = New-Object System.Drawing.Size(520, 270)
    $dlg.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
    $dlg.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    $dlg.BackColor = [System.Drawing.Color]::FromArgb(15, 23, 42)
    $dlg.ForeColor = [System.Drawing.Color]::White

    $lblInfo = New-Object System.Windows.Forms.Label
    $lblInfo.Text = "Target Account: $($u.DisplayName)`nsAMAccountName: $($u.SamAccountName)  |  UPN: $($u.UserPrincipalName)"
    $lblInfo.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
    $lblInfo.ForeColor = [System.Drawing.Color]::FromArgb(56, 189, 248)
    $lblInfo.Location = New-Object System.Drawing.Point(20, 15)
    $lblInfo.Size = New-Object System.Drawing.Size(460, 40)
    $dlg.Controls.Add($lblInfo)

    $lblPrompt = New-Object System.Windows.Forms.Label
    $lblPrompt.Text = "Choose or Type New Temporary Password:"
    $lblPrompt.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $lblPrompt.Location = New-Object System.Drawing.Point(20, 60)
    $lblPrompt.Size = New-Object System.Drawing.Size(460, 20)
    $dlg.Controls.Add($lblPrompt)

    $txtPass = New-Object System.Windows.Forms.TextBox
    $txtPass.Location = New-Object System.Drawing.Point(20, 83)
    $txtPass.Size = New-Object System.Drawing.Size(320, 26)
    $txtPass.Font = New-Object System.Drawing.Font("Consolas", 10, [System.Drawing.FontStyle]::Bold)
    $txtPass.Text = "Secure#" + (Get-Random -Minimum 1000 -Maximum 9999) + "!Safe"
    $dlg.Controls.Add($txtPass)

    $btnGen = New-Object System.Windows.Forms.Button
    $btnGen.Text = "Generate"
    $btnGen.Location = New-Object System.Drawing.Point(348, 82)
    $btnGen.Size = New-Object System.Drawing.Size(75, 28)
    $btnGen.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnGen.BackColor = [System.Drawing.Color]::FromArgb(30, 41, 59)
    $btnGen.ForeColor = [System.Drawing.Color]::White
    $btnGen.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnGen.Add_Click({
        $chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*"
        $rnd = New-Object System.Random
        $newP = -join (1..16 | ForEach-Object { $chars[$rnd.Next(0, $chars.Length)] }) + "1!"
        $txtPass.Text = $newP
    })
    $dlg.Controls.Add($btnGen)

    $btnCopy = New-Object System.Windows.Forms.Button
    $btnCopy.Text = "Copy"
    $btnCopy.Location = New-Object System.Drawing.Point(428, 82)
    $btnCopy.Size = New-Object System.Drawing.Size(55, 28)
    $btnCopy.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $btnCopy.BackColor = [System.Drawing.Color]::FromArgb(30, 41, 59)
    $btnCopy.ForeColor = [System.Drawing.Color]::White
    $btnCopy.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCopy.Add_Click({
        if (-not [string]::IsNullOrEmpty($txtPass.Text)) {
            [System.Windows.Forms.Clipboard]::SetText($txtPass.Text)
            [System.Windows.Forms.MessageBox]::Show($dlg, "Password copied to clipboard!", "Copied", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
        }
    })
    $dlg.Controls.Add($btnCopy)

    $chkMustChange = New-Object System.Windows.Forms.CheckBox
    $chkMustChange.Text = "Require user to change password at next logon (pwdLastSet = 0)"
    $chkMustChange.Checked = $true
    $chkMustChange.Location = New-Object System.Drawing.Point(22, 118)
    $chkMustChange.Size = New-Object System.Drawing.Size(460, 24)
    $chkMustChange.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $dlg.Controls.Add($chkMustChange)

    $btnSubmit = New-Object System.Windows.Forms.Button
    $btnSubmit.Text = "Reset Password Now"
    $btnSubmit.Location = New-Object System.Drawing.Point(180, 165)
    $btnSubmit.Size = New-Object System.Drawing.Size(180, 36)
    $btnSubmit.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
    $btnSubmit.BackColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
    $btnSubmit.ForeColor = [System.Drawing.Color]::White
    $btnSubmit.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnSubmit.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $dlg.Controls.Add($btnSubmit)

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Cancel"
    $btnCancel.Location = New-Object System.Drawing.Point(370, 165)
    $btnCancel.Size = New-Object System.Drawing.Size(110, 36)
    $btnCancel.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    $btnCancel.BackColor = [System.Drawing.Color]::FromArgb(51, 65, 85)
    $btnCancel.ForeColor = [System.Drawing.Color]::White
    $btnCancel.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlg.Controls.Add($btnCancel)

    $dlg.AcceptButton = $btnSubmit
    $dlg.CancelButton = $btnCancel

    $diagResult = $dlg.ShowDialog($form)
    if ($diagResult -eq [System.Windows.Forms.DialogResult]::OK) {
        $chosenPass = $txtPass.Text.Trim()
        if ([string]::IsNullOrEmpty($chosenPass)) {
            [System.Windows.Forms.MessageBox]::Show($form, "Password cannot be empty.", "Validation Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
            return
        }

        if (-not $script:isDomainJoined -and -not (Test-ValidADServer $script:targetServer)) {
            Write-AppLog "Active Directory domain is not linked. Please check Tab 2 ('Health & Diagnostics') or click 'Switch Domain / DC'." "WARN"
            Prompt-CheckDiagnosticsTab -ServiceName "Active Directory" -Reason "No Active Directory domain or Domain Controller is connected." -SetupInstruction "Click 'Switch Domain / DC' in the top-right header or check Tab 2 ('Health & Diagnostics') to test Active Directory connectivity."
            return
        }

        Write-AppLog "Executing Active Directory password reset for '$($u.SamAccountName)' ($($u.UserPrincipalName)) with custom chosen password..." "INFO"
        try {
            Set-ADPasswordSafe -SamAccount $u.SamAccountName -NewPassword $chosenPass -Server $script:targetServer -Cred $script:adCredential
            $lblCardPassVal.Text = "0 days (Reset)"
            $lblCardPassSub.Text = if ($chkMustChange.Checked) { "Must change at logon" } else { "Password updated" }
            if ($txtCustomPass) { $txtCustomPass.Text = $chosenPass }
            Write-AppLog "SUCCESS: Active Directory password successfully reset and verified for '$($u.SamAccountName)'. New password active." "SUCCESS"
            Add-AuditEntry "Reset Password" "SUCCESS" "Active Directory password reset and verified for sAM '$($u.SamAccountName)'."
            [System.Windows.Forms.MessageBox]::Show($form, "Active Directory password for '$($u.DisplayName)' has been successfully reset!`n`nTemporary Password: $chosenPass", "Password Reset Successful", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
        } catch {
            Write-AppLog "ERROR: Password reset failed: $($_.Exception.Message)" "ERROR"
            Add-AuditEntry "Reset Password" "FAILED" $_.Exception.Message
            [System.Windows.Forms.MessageBox]::Show($form, "Password reset failed:`n$($_.Exception.Message)", "Password Reset Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    }
}

# ACTION 1: Password Reset Button -> Opens custom password dialog allowing operator to choose/generate password
$btnResetPass.Add_Click({
    Show-PasswordResetCustomDialog
})

# ACTION 2: Revoke 365 Sessions (Uses Verified Graph Context & Multi-Attribute Matching)
$btnRevoke365.Add_Click({
    if ($null -eq $script:currentUser) { return }
    $targetGraphId = if ($script:currentUser.GraphTargetId) { $script:currentUser.GraphTargetId } else { $script:currentUser.UserPrincipalName }
    Write-AppLog "Verifying Microsoft Graph session before revoking tokens for '$targetGraphId'..." "INFO"
    try {
        $graphCheck = Invoke-VerifyGraph
        if (-not $graphCheck.Verified) {
            Write-AppLog "Microsoft Graph account is not linked ($($graphCheck.Error)). Please check Tab 1 ('1. Setup') to link Microsoft Graph." "WARN"
            Prompt-CheckDiagnosticsTab -ServiceName "Microsoft Graph (Entra ID / 365)" -Reason $graphCheck.Error -SetupInstruction "Open Tab 1 ('1. Setup') and click '1. Setup Microsoft Graph' to install the required modules and sign in."
            return
        }

        $revokeInfo = Invoke-RevokeMgUserSignInSessionSafe -UserPrincipalName $targetGraphId -CandidateIds $script:currentUser.CloudCandidates -SamAccountName $script:currentUser.SamAccountName
        $activeCtx = $revokeInfo.Context
        $matchedGraphUser = $revokeInfo.MatchedUserId
        $script:currentUser.GraphTargetId = $matchedGraphUser
        $verifiedAcct = if ($activeCtx -and $activeCtx.Account) { $activeCtx.Account } else { $graphCheck.Account }

        $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($verifiedAcct)"
        $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        $lblCard365Val.Text = "Sessions Revoked"
        $lblCard365Sub.Text = "Login Capable (Not Blocked)"
        Write-AppLog "SUCCESS: Microsoft 365 / Entra ID refresh tokens and sessions revoked and verified for '$matchedGraphUser'." "SUCCESS"
        Add-AuditEntry "Revoke 365 Sessions" "SUCCESS" "Revoke-MgUserSignInSession verified for Entra ID '$matchedGraphUser' by $verifiedAcct."
        Show-ActionPopup -ActionTitle "Revoke 365 Sessions" -Succeeded $true -Details "Microsoft 365 / Entra ID sessions & refresh tokens revoked for '$matchedGraphUser'."
    }
    catch {
        Write-AppLog "ERROR: Microsoft Graph session revocation failed: $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "Revoke 365 Sessions" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle "Revoke 365 Sessions" -Succeeded $false -Details $_.Exception.Message
    }
})

# ACTION 3: Revoke Google Sessions (Uses Verified GAM7 & Multi-Attribute Email/UPN Matching)
$btnRevokeGoogle.Add_Click({
    if ($null -eq $script:currentUser) { return }
    $targetGamId = if ($script:currentUser.GamTargetId) { $script:currentUser.GamTargetId } else { $script:currentUser.UserPrincipalName }
    Write-AppLog "Verifying GAM7 installation & OAuth before revoking Google Workspace sessions for '$targetGamId'..." "INFO"
    try {
        $gamCheck = Invoke-VerifyGAM
        if (-not $gamCheck.Verified) {
            Write-AppLog "Google Workspace (GAM7) account is not linked ($($gamCheck.Error)). Please check Tab 1 ('1. Setup') to link Google GAM7." "WARN"
            Prompt-CheckDiagnosticsTab -ServiceName "Google Workspace (GAM7)" -Reason $gamCheck.Error -SetupInstruction "Open Tab 1 ('1. Setup') and click '2. Setup Google GAM7' to install GAM7 and authorize Google Workspace OAuth."
            return
        }

        $gamExe = $gamCheck.Executable
        Write-AppLog "Executing GAM7 signout for '$targetGamId' (with fallback across AD mail/UPN candidates)..." "INFO"
        $gamRes = Invoke-GamUserSignoutSafe -GamExecutable $gamExe -PrimaryTarget $targetGamId -CandidateIds $script:currentUser.CloudCandidates
        $matchedGamUser = $gamRes.MatchedUserId
        $script:currentUser.GamTargetId = $matchedGamUser

        $lblCardGoogleVal.Text = "Sessions Revoked"
        $lblCardGoogleSub.Text = "Login Capable (Not Blocked)"
        if ($gamRes.Output) {
            Write-AppLog "GAM Output: $($gamRes.Output)" "INFO"
        }
        Write-AppLog "SUCCESS: Google Workspace web sessions and OAuth tokens revoked and verified via GAM7 for '$matchedGamUser'." "SUCCESS"
        Add-AuditEntry "Revoke Google Sessions" "SUCCESS" "GAM signout verified (exit code 0) for Google Workspace user '$matchedGamUser'."
        Show-ActionPopup -ActionTitle "Revoke Google Sessions" -Succeeded $true -Details "Google Workspace web sessions & cookies signed out for '$matchedGamUser'."
    }
    catch {
        Write-AppLog "ERROR: Google Workspace session revocation failed: $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "Revoke Google Sessions" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle "Revoke Google Sessions" -Succeeded $false -Details $_.Exception.Message
    }
})

# ACTION 4: Disable / Enable AD Account (With Post-Action LDAP Verification)
$btnEmergencyLock.Add_Click({
    if ($null -eq $script:currentUser) { return }
    if (-not $script:isDomainJoined -and -not (Test-ValidADServer $script:targetServer)) {
        Write-AppLog "Active Directory domain is not linked. Please check Tab 1 ('1. Setup') or click 'Switch Domain / DC'." "WARN"
        Prompt-CheckDiagnosticsTab -ServiceName "Active Directory" -Reason "No Active Directory domain or Domain Controller is connected." -SetupInstruction "Click 'Switch Domain / DC' in the top-right header or check Tab 1 ('1. Setup') to verify your Active Directory connection."
        return
    }
    $targetEnableState = -not [bool]$script:currentUser.Enabled
    $actionVerb = if ($targetEnableState) { "Re-enabling" } else { "Disabling" }
    $actTitle = if ($targetEnableState) { "Enable AD Account" } else { "Disable AD Account" }
    Write-AppLog "$actionVerb Active Directory account '$($script:currentUser.SamAccountName)'..." "INFO"
    try {
        Set-ADAccountEnableSafe -SamAccount $script:currentUser.SamAccountName -Enable $targetEnableState -Server $script:targetServer -Cred $script:adCredential
        $script:currentUser.Enabled = $targetEnableState

        if ($targetEnableState) {
            $lblCardAcctVal.Text = "ACTIVE"
            $lblCardAcctSub.Text = "Verified Enabled in AD"
            $btnEmergencyLock.Text = "4. Disable Account"
            Write-AppLog "SUCCESS: Account '$($script:currentUser.SamAccountName)' re-enabled and verified in Active Directory." "SUCCESS"
            Add-AuditEntry "Enable Account" "SUCCESS" "Account '$($script:currentUser.SamAccountName)' re-enabled and verified in Active Directory."
            Show-ActionPopup -ActionTitle $actTitle -Succeeded $true -Details "Active Directory account '$($script:currentUser.SamAccountName)' is now ENABLED."
        } else {
            $lblCardAcctVal.Text = "DISABLED"
            $lblCardAcctSub.Text = "Verified Disabled in AD"
            $btnEmergencyLock.Text = "4. Enable Account"
            Write-AppLog "SUCCESS: Account '$($script:currentUser.SamAccountName)' disabled and verified in Active Directory." "SUCCESS"
            Add-AuditEntry "Disable Account" "SUCCESS" "Account '$($script:currentUser.SamAccountName)' disabled and verified in Active Directory."
            Show-ActionPopup -ActionTitle $actTitle -Succeeded $true -Details "Active Directory account '$($script:currentUser.SamAccountName)' is now DISABLED."
        }
    }
    catch {
        Write-AppLog "ERROR: Account enable/disable operation failed: $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "Disable/Enable Account" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle $actTitle -Succeeded $false -Details $_.Exception.Message
    }
})

# ACTION 5: 1-Click Full Containment Playbook (Real Execution + Single Consolidated Popup)
$btnContainAll.Add_Click({
    if ($null -eq $script:currentUser) { return }
    Write-AppLog "=== STARTING AUTOMATED INCIDENT CONTAINMENT PLAYBOOK ===" "INFO"

    $passedSteps = [System.Collections.Generic.List[string]]::new()
    $failedSteps = [System.Collections.Generic.List[string]]::new()

    $tempPass = if (-not [string]::IsNullOrEmpty($txtCustomPass.Text.Trim())) {
        $txtCustomPass.Text.Trim()
    } else {
        "Secure#" + (Get-Random -Minimum 1000 -Maximum 9999) + "!Safe"
    }

    # Step 1: Reset AD Password
    Write-AppLog "[1/4] Resetting Active Directory password for '$($script:currentUser.SamAccountName)'..." "INFO"
    try {
        Set-ADPasswordSafe -SamAccount $script:currentUser.SamAccountName -NewPassword $tempPass -Server $script:targetServer -Cred $script:adCredential
        $lblCardPassVal.Text = "0 days (Reset)"
        $lblCardPassSub.Text = "Temp: $tempPass"
        $passedSteps.Add("1. AD Password Reset (Temp: $tempPass)")
        Write-AppLog "  -> [PASS] Active Directory password reset to '$tempPass' and verified." "SUCCESS"
    } catch {
        $failedSteps.Add("1. AD Password Reset: $($_.Exception.Message)")
        Write-AppLog "  -> [FAIL] Active Directory password reset failed: $($_.Exception.Message)" "ERROR"
    }

    # Step 2: Revoke Microsoft 365 Sessions via Graph
    $targetGraphId = if ($script:currentUser.GraphTargetId) { $script:currentUser.GraphTargetId } else { $script:currentUser.UserPrincipalName }
    Write-AppLog "[2/4] Revoking Microsoft 365 / Entra ID sessions via Microsoft Graph for '$targetGraphId'..." "INFO"
    try {
        $graphCheck = Invoke-VerifyGraph
        if (-not $graphCheck.Verified) {
            throw $graphCheck.Error
        }
        $revInfo = Invoke-RevokeMgUserSignInSessionSafe -UserPrincipalName $targetGraphId -CandidateIds $script:currentUser.CloudCandidates -SamAccountName $script:currentUser.SamAccountName
        $matchedGraphId = $revInfo.MatchedUserId
        $script:currentUser.GraphTargetId = $matchedGraphId
        $lblCard365Val.Text = "Sessions Revoked"
        $lblCard365Sub.Text = "Login Capable (Not Blocked)"
        $passedSteps.Add("2. M365 Token Revocation ($matchedGraphId)")
        Write-AppLog "  -> [PASS] Microsoft 365 refresh tokens invalidated and verified for '$matchedGraphId'." "SUCCESS"
    } catch {
        $failedSteps.Add("2. M365 Revocation: $($_.Exception.Message)")
        Write-AppLog "  -> [FAIL] Microsoft Graph revocation failed: $($_.Exception.Message)" "ERROR"
    }

    # Step 3: Revoke Google Workspace Sessions via GAM7
    $targetGamId = if ($script:currentUser.GamTargetId) { $script:currentUser.GamTargetId } else { $script:currentUser.UserPrincipalName }
    Write-AppLog "[3/4] Revoking Google Workspace sessions via GAM7 for '$targetGamId'..." "INFO"
    try {
        $gamCheck = Invoke-VerifyGAM
        if (-not $gamCheck.Verified) {
            throw $gamCheck.Error
        }
        $gamExe = $gamCheck.Executable
        $gamRes = Invoke-GamUserSignoutSafe -GamExecutable $gamExe -PrimaryTarget $targetGamId -CandidateIds $script:currentUser.CloudCandidates
        $matchedGamId = $gamRes.MatchedUserId
        $script:currentUser.GamTargetId = $matchedGamId
        $lblCardGoogleVal.Text = "Sessions Revoked"
        $lblCardGoogleSub.Text = "Login Capable (Not Blocked)"
        $passedSteps.Add("3. Google GAM Signout ($matchedGamId)")
        Write-AppLog "  -> [PASS] Google Workspace sessions wiped and verified via GAM7 for '$matchedGamId'." "SUCCESS"
    } catch {
        $failedSteps.Add("3. Google GAM Signout: $($_.Exception.Message)")
        Write-AppLog "  -> [FAIL] Google Workspace revocation failed: $($_.Exception.Message)" "ERROR"
    }

    # Step 4: Disable AD Account
    Write-AppLog "[4/4] Disabling Active Directory account '$($script:currentUser.SamAccountName)'..." "INFO"
    try {
        Set-ADAccountEnableSafe -SamAccount $script:currentUser.SamAccountName -Enable $false -Server $script:targetServer -Cred $script:adCredential
        $script:currentUser.Enabled = $false
        $lblCardAcctVal.Text = "DISABLED"
        $lblCardAcctSub.Text = "Verified Disabled in AD"
        $btnEmergencyLock.Text = "4. Enable Account"
        $passedSteps.Add("4. AD Account Disabled ($($script:currentUser.SamAccountName))")
        Write-AppLog "  -> [PASS] Active Directory account disabled and verified." "SUCCESS"
    } catch {
        $failedSteps.Add("4. AD Account Disable: $($_.Exception.Message)")
        Write-AppLog "  -> [FAIL] Active Directory account disable failed: $($_.Exception.Message)" "ERROR"
    }

    $nl = [System.Environment]::NewLine
    if ($failedSteps.Count -eq 0) {
        Add-AuditEntry "Full Containment Playbook" "SUCCESS" "All 4 steps verified: $($passedSteps -join '; ')"
        Write-AppLog "=== PLAYBOOK COMPLETE: ALL 4 CONTAINMENT STEPS VERIFIED ===" "SUCCESS"
        $summaryText = "All 4 containment steps succeeded for '$($script:currentUser.DisplayName)':$nl$nl- " + ($passedSteps -join "$nl- ")
        Show-ActionPopup -ActionTitle "Full Containment Playbook (4/4)" -Succeeded $true -Details $summaryText
    } elseif ($passedSteps.Count -gt 0) {
        Add-AuditEntry "Full Containment Playbook" "PARTIAL" "Passed: $($passedSteps -join '; ') | Failed: $($failedSteps -join '; ')"
        Write-AppLog "=== PLAYBOOK PARTIAL: $($passedSteps.Count)/4 passed, $($failedSteps.Count)/4 failed. See log below. ===" "WARN"
        $summaryText = "Passed ($($passedSteps.Count)/4):${nl}- " + ($passedSteps -join "${nl}- ") + "${nl}${nl}Failed ($($failedSteps.Count)/4):${nl}- " + ($failedSteps -join "${nl}- ")
        Show-ActionPopup -ActionTitle "Full Containment Playbook (Partial)" -Succeeded $false -Details $summaryText
    } else {
        Add-AuditEntry "Full Containment Playbook" "FAILED" "All steps failed: $($failedSteps -join '; ')"
        Write-AppLog "=== PLAYBOOK FAILED: 0/4 steps succeeded. Check Tab 1 ('1. Setup') to link accounts. ===" "ERROR"
        $summaryText = "0/4 steps succeeded:$nl- " + ($failedSteps -join "$nl- ")
        Show-ActionPopup -ActionTitle "Full Containment Playbook" -Succeeded $false -Details $summaryText
    }
})

