                     "   - Uses native .NET LDAP / ADSI out-of-the-box, or the RSAT ActiveDirectory module if installed.`r`n" +
                     "   - If running from a non-domain-joined workstation, click 'Switch Domain / DC' in the top-right header to specify a Domain Controller and Domain Admin credentials.`r`n`r`n" +
