                     "   - Click '2. Setup Google GAM7' above to install/configure GAM7 and authorize Google Workspace Admin OAuth.`r`n" +
                     "   - All test and setup output streams live to the shared 'Real-Time Action Log & Diagnostics' panel below."
$grpDiagGuide.Controls.Add($lblDiagGuide)

function Write-DiagLog {
    param([string]$Message)
    $lvl = if ($Message -match '^\[FAIL\]|^\[ERROR\]') { "ERROR" } elseif ($Message -match '^\[PASS\]|^\[SUCCESS\]') { "SUCCESS" } elseif ($Message -match '^\[WARN\]') { "WARN" } else { "INFO" }
    Write-AppLog $Message $lvl
}

$btnTestAD.Add_Click({
    Write-DiagLog "=== VERIFYING ACTIVE DIRECTORY CONNECTIVITY (LIVE LDAP RootDSE) ==="
    $adCheck = Invoke-VerifyAD
    if ($adCheck.Verified) {
        $lblStatusAD.Text = "Active Directory: VERIFIED ($($adCheck.Domain) - $($adCheck.Engine))"
        $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        Write-DiagLog "[PASS] Active Directory LDAP handshake verified! Domain: $($adCheck.Domain) | Engine: $($adCheck.Engine)"
        Show-ActionPopup -ActionTitle "Test Active Directory" -Succeeded $true -Details "Domain: $($adCheck.Domain)`nEngine: $($adCheck.Engine)"
    } else {
        $lblStatusAD.Text = "Active Directory: FAILED / NOT CONNECTED ($($adCheck.Error))"
        $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        Write-DiagLog "[FAIL] Active Directory verification failed: $($adCheck.Error)"
        Show-ActionPopup -ActionTitle "Test Active Directory" -Succeeded $false -Details $adCheck.Error
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnTestM365.Add_Click({
    Write-DiagLog "=== VERIFYING MICROSOFT GRAPH SDK, SCOPES & LIVE TOKEN ==="
    $graphCheck = Invoke-VerifyGraph -LiveApiCheck
    if ($graphCheck.Verified) {
        $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($($graphCheck.Account))"
        $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        Write-DiagLog "[PASS] Microsoft Graph verified! Account: $($graphCheck.Account) | TenantId: $($graphCheck.TenantId)"
        if ($script:currentUser) { Update-SelectedUserSessionBoxes }
        Show-ActionPopup -ActionTitle "Test Microsoft Graph" -Succeeded $true -Details "Account: $($graphCheck.Account)`nTenant: $($graphCheck.TenantId)"
    } else {
        $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: NOT VERIFIED ($($graphCheck.Error))"
        $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        Write-DiagLog "[FAIL] Microsoft Graph verification failed: $($graphCheck.Error)"
        Show-ActionPopup -ActionTitle "Test Microsoft Graph" -Succeeded $false -Details $graphCheck.Error
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnTestGoogle.Add_Click({
    Write-DiagLog "=== VERIFYING GOOGLE APPS MANAGER (GAM7) & OAUTH ==="
    $gamCheck = Invoke-VerifyGAM
    if ($gamCheck.Verified) {
        $lblStatusGAM.Text = "Google Apps Manager (GAM7): VERIFIED (v$($gamCheck.Version) & OAuth Ready)"
        $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        Write-DiagLog "[PASS] GAM7 v$($gamCheck.Version) and Google Workspace OAuth verified at $($gamCheck.Executable)!"
        if ($script:currentUser) { Update-SelectedUserSessionBoxes }
        Show-ActionPopup -ActionTitle "Test Google GAM7" -Succeeded $true -Details "GAM7 Version: v$($gamCheck.Version)`nPath: $($gamCheck.Executable)"
    } else {
        $lblStatusGAM.Text = "Google Apps Manager (GAM7): NOT VERIFIED ($($gamCheck.Error))"
        $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        Write-DiagLog "[FAIL] GAM7 verification failed: $($gamCheck.Error)"
        Show-ActionPopup -ActionTitle "Test Google GAM7" -Succeeded $false -Details $gamCheck.Error
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnRunGraphSetup.Add_Click({
    try {
        Write-DiagLog "Launching Setup-MicrosoftGraph.bat..."
        $exitCode = Invoke-SetupBatchScript -FileName "Setup-MicrosoftGraph.bat" -Base64Payload $script:EmbeddedGraphBatB64
        Write-DiagLog "Setup-MicrosoftGraph.bat exited with code $exitCode. Running post-setup verification..."
        $graphCheck = Invoke-VerifyGraph -LiveApiCheck
        if ($exitCode -eq 0 -and $graphCheck.Verified) {
            Write-DiagLog "[SUCCESS] Microsoft Graph verified for $($graphCheck.Account) (Tenant: $($graphCheck.TenantId))."
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($($graphCheck.Account))"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            if ($script:currentUser) { Update-SelectedUserSessionBoxes }
            Show-ActionPopup -ActionTitle "Setup Microsoft Graph" -Succeeded $true -Details "Verified account: $($graphCheck.Account)"
        } else {
            Write-DiagLog "[FAIL] Microsoft Graph setup did not verify: $($graphCheck.Error)"
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: SETUP INCOMPLETE"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
            Show-ActionPopup -ActionTitle "Setup Microsoft Graph" -Succeeded $false -Details $graphCheck.Error
        }
    } catch {
        Write-DiagLog "[ERROR] Microsoft Graph setup error: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Setup Microsoft Graph" -Succeeded $false -Details $_.Exception.Message
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnRunGamSetup.Add_Click({
    try {
        Write-DiagLog "Launching Setup-GoogleWorkspace-GAM.bat..."
        $exitCode = Invoke-SetupBatchScript -FileName "Setup-GoogleWorkspace-GAM.bat" -Base64Payload $script:EmbeddedGamBatB64
        Write-DiagLog "Setup-GoogleWorkspace-GAM.bat exited with code $exitCode. Running post-setup verification..."
        $gamCheck = Invoke-VerifyGAM
        if ($gamCheck.Verified) {
            Write-DiagLog "[SUCCESS] GAM7 v$($gamCheck.Version) installed at $($gamCheck.Executable) and OAuth verified."
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): VERIFIED (v$($gamCheck.Version) & OAuth Ready)"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            if ($script:currentUser) { Update-SelectedUserSessionBoxes }
            Show-ActionPopup -ActionTitle "Setup Google GAM7" -Succeeded $true -Details "GAM7 v$($gamCheck.Version) verified."
        } else {
            Write-DiagLog "[WARN] GAM7 post-setup status: $($gamCheck.Error)"
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): $(if($gamCheck.Installed){'INSTALLED - OAUTH PENDING'}else{'NOT INSTALLED'})"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
            Show-ActionPopup -ActionTitle "Setup Google GAM7" -Succeeded $false -Details $gamCheck.Error
        }
    } catch {
        Write-DiagLog "[ERROR] Google Workspace GAM setup error: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Setup Google GAM7" -Succeeded $false -Details $_.Exception.Message
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnRunRsatSetup.Add_Click({
    try {
        Write-DiagLog "Launching Setup-RSAT-ActiveDirectory.bat (requires Administrator elevation)..."
        $exitCode = Invoke-SetupBatchScript -FileName "Setup-RSAT-ActiveDirectory.bat" -Base64Payload $script:EmbeddedRsatBatB64 -Elevate
        Write-DiagLog "Setup-RSAT-ActiveDirectory.bat exited with code $exitCode. Verifying ActiveDirectory module..."
        if ($exitCode -eq 0 -and (Get-Module -ListAvailable -Name ActiveDirectory)) {
            Import-Module ActiveDirectory -ErrorAction SilentlyContinue
            Write-DiagLog "[SUCCESS] ActiveDirectory RSAT PowerShell module is installed and verified."
            Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $true -Details "RSAT ActiveDirectory module installed and verified."
        } else {
            Write-DiagLog "[WARN] RSAT ActiveDirectory module was not detected after installer exited (code $exitCode). Native .NET LDAP remains active."
            Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $false -Details "RSAT module not detected (Native .NET LDAP remains active)."
        }
    } catch {
        Write-DiagLog "[ERROR] RSAT setup error: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $false -Details $_.Exception.Message
    }
})

