function Load-ForwardingRulesGrid {
    param([switch]$ShowPopupOnComplete)
    if ($null -eq $script:currentUser) {
        $txtRuleDecision.Text = "No user selected. Search and select a user on Tab 2 ('2. Containment') first."
        return
    }
    try {
        $gridRules.Rows.Clear()
        $script:loadedForwardingRules = @()
        Update-RuleActionButtonsState
        Write-AppLog "Auditing Microsoft 365 Inbox/Forwarding Rules (Graph) and Gmail Forwarding/Filters (GAM7) for '$($script:currentUser.DisplayName)'..." "INFO"
        $txtRuleDecision.Text = "Scanning Microsoft 365 Inbox Rules (Graph API) and Gmail Forwarding/Filters (GAM7) for '$($script:currentUser.DisplayName)'..."
        $form.Refresh()

        $auditRes = Get-UserForwardingAndInboxRulesSafe -UserObj $script:currentUser
        $rawRules = @()
        if ($auditRes -and $null -ne $auditRes.Rules) {
            $rawRules = if ($auditRes.Rules -is [array]) { $auditRes.Rules } else { @($auditRes.Rules) }
        }
        $script:loadedForwardingRules = $rawRules

        $suspiciousCount = 0
        foreach ($r in $rawRules) {
            if ($null -eq $r) { continue }
            $p1 = "Mailbox Rule"
            if ($r.PSObject.Properties['Provider'] -and $r.Provider) { $p1 = [string]$r.Provider }
            elseif ($r.PSObject.Properties['Platform'] -and $r.Platform) { $p1 = [string]$r.Platform }

            $p2 = "Rule"
            if ($r.PSObject.Properties['RuleType'] -and $r.RuleType) { $p2 = [string]$r.RuleType }
            elseif ($r.PSObject.Properties['RuleId'] -and $r.RuleId) { $p2 = [string]$r.RuleId }

            $p3 = "Unnamed Rule"
            if ($r.PSObject.Properties['RuleName'] -and $r.RuleName) { $p3 = [string]$r.RuleName }

            $p4 = "ENABLED"
            if ($r.PSObject.Properties['State'] -and $r.State) { $p4 = [string]$r.State }
            elseif ($r.PSObject.Properties['Enabled']) {
                if ($r.Enabled) { $p4 = "ENABLED" } else { $p4 = "DISABLED" }
            }

            $p5 = "NORMAL"
            if ($r.PSObject.Properties['Risk'] -and $r.Risk) { $p5 = [string]$r.Risk }

            $p6 = ""
            if ($r.PSObject.Properties['ActionDest'] -and $r.ActionDest) { $p6 = [string]$r.ActionDest }
            elseif ($r.PSObject.Properties['Summary'] -and $r.Summary) { $p6 = [string]$r.Summary }

            # Use parameterless Rows.Add() and direct cell assignment to avoid PowerShell array overload mismatch
            $rowIdx = $gridRules.Rows.Add()
            if ($rowIdx -ge 0) {
                $rRow = $gridRules.Rows[$rowIdx]
                $rRow.Cells[0].Value = $p1
                $rRow.Cells[1].Value = $p2
                $rRow.Cells[2].Value = $p3
                $rRow.Cells[3].Value = $p4
                $rRow.Cells[4].Value = $p5
                $rRow.Cells[5].Value = $p6

                $riskCell = $rRow.Cells["colRuleRisk"]
                if ($p5 -like "*HIGH*" -or $p5 -like "*SUSPICIOUS*") {
                    $suspiciousCount++
                    $riskCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(248, 113, 113)
                } else {
                    $riskCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(52, 211, 153)
                }
            }
        }

        if ($gridRules.Rows.Count -gt 0) {
            $gridRules.Rows[0].Selected = $true
        }
        Update-RuleActionButtonsState

        $statusMsg = "Audited $($rawRules.Count) rule(s)/filter(s) ($suspiciousCount flagged HIGH RISK / SUSPICIOUS)."
        if ($auditRes -and $auditRes.Diagnostics) {
            $statusMsg += " Diagnostics: $($auditRes.Diagnostics)"
        }
        $txtRuleDecision.Text = "$statusMsg Select any row above to Disable, Enable, or Delete a rule."
        Write-AppLog "SUCCESS: Forwarding & Inbox Rules Audit completed for '$($script:currentUser.UserPrincipalName)': $statusMsg" "SUCCESS"
        Add-AuditEntry "Audit Email Forwarding & Rules" "SUCCESS" $statusMsg
        if ($ShowPopupOnComplete) {
            Show-ActionPopup -ActionTitle "Audit Forwarding & Inbox Rules" -Succeeded $true -Details $statusMsg
        }
    } catch {
        $errText = $_.Exception.Message
        $txtRuleDecision.Text = "AUDIT ERROR: $errText"
        Write-AppLog "ERROR: Mailbox Rules Audit Failed: $errText" "ERROR"
        Add-AuditEntry "Audit Email Forwarding & Rules" "FAILED" $errText
        if ($ShowPopupOnComplete) {
            Show-ActionPopup -ActionTitle "Audit Forwarding & Inbox Rules" -Succeeded $false -Details $errText
        }
    }
}

$btnAuditForwardingRules.Add_Click({
    Load-ForwardingRulesGrid -ShowPopupOnComplete
})

function Invoke-SelectedRuleOperation {
    param([ValidateSet("Disable", "Enable", "Delete")][string]$Operation)
    if ($null -eq $script:currentUser -or $gridRules.SelectedRows.Count -le 0) { return }
    $idx = $gridRules.SelectedRows[0].Index
    if ($idx -lt 0 -or $idx -ge $script:loadedForwardingRules.Count) { return }
    $ruleObj = $script:loadedForwardingRules[$idx]
    $verbIng = switch ($Operation) {
        "Enable"  { "Enabling" }
        "Delete"  { "Deleting" }
        default   { "Disabling" }
    }
    Write-AppLog "$verbIng selected email rule '$($ruleObj.RuleName)' (Provider: $($ruleObj.Provider), ID: $($ruleObj.RuleId))..." "INFO"
    try {
        $remRes = Disable-OrRemoveForwardingRuleSafe -RuleObj $ruleObj -Operation $Operation
        $detailsStr = if ($remRes -is [hashtable] -and $remRes.Details) { [string]$remRes.Details } else { [string]$remRes }
        Write-AppLog "SUCCESS: $detailsStr" "SUCCESS"
        Add-AuditEntry "$Operation Email Rule" "SUCCESS" $detailsStr
        Load-ForwardingRulesGrid
        Show-ActionPopup -ActionTitle "$Operation Selected Rule" -Succeeded $true -Details $detailsStr
    } catch {
        Write-AppLog "ERROR: Failed to $($Operation.ToLowerInvariant()) rule '$($ruleObj.RuleName)': $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "$Operation Email Rule" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle "$Operation Selected Rule" -Succeeded $false -Details $_.Exception.Message
    }
}

$btnDisableSelectedRule.Add_Click({
    Invoke-SelectedRuleOperation -Operation "Disable"
})

$btnEnableSelectedRule.Add_Click({
    Invoke-SelectedRuleOperation -Operation "Enable"
})

$btnDeleteSelectedRule.Add_Click({
    Invoke-SelectedRuleOperation -Operation "Delete"
})

$btnDisableAllSuspiciousRules.Add_Click({
    if ($null -eq $script:currentUser -or $script:loadedForwardingRules.Count -eq 0) { return }
    $suspiciousList = @($script:loadedForwardingRules | Where-Object { $_.Risk -like "*HIGH*" -or $_.Risk -like "*SUSPICIOUS*" })
    if ($suspiciousList.Count -eq 0) { return }

    Write-AppLog "Disabling all $($suspiciousList.Count) suspicious forwarding/inbox rules for '$($script:currentUser.UserPrincipalName)'..." "INFO"
    $remediated = 0
    foreach ($sRule in $suspiciousList) {
        try {
            $null = Disable-OrRemoveForwardingRuleSafe -RuleObj $sRule -Operation "Disable"
            $remediated++
        } catch {
            Write-AppLog "WARN: Could not disable rule '$($sRule.RuleName)': $($_.Exception.Message)" "WARN"
        }
    }
    $msg = "Disabled/removed $remediated of $($suspiciousList.Count) suspicious forwarding/inbox rule(s)."
    Write-AppLog "SUCCESS: $msg" "SUCCESS"
    Add-AuditEntry "Disable All Suspicious Rules" "SUCCESS" $msg
    Load-ForwardingRulesGrid
    Show-ActionPopup -ActionTitle "Disable All Suspicious Rules" -Succeeded ($remediated -gt 0) -Details $msg
})

