function Clear-SecurityEventsResults {
    if ($gridEvents) { $gridEvents.Rows.Clear() }
    $script:allPulledEvents = @()
    $script:filteredEvents = @()
    $script:savedUserPulledEvents = @()
    if ($btnRestorePulledEvents) {
        $btnRestorePulledEvents.Enabled = $false
        $btnRestorePulledEvents.Text = "Show Pulled Events"
    }
    if ($lblEventStats) {
        $lblEventStats.Text = "Deciphers AD (4624/4625/4740/4768/4769/4771/4776/4720-4738/4778), Entra (50173/50057/50126/50053/53003/MFA/OAuth/Risk), & Google GAM7."
    }
    if ($txtEventDecision) {
        $txtEventDecision.Text = "Select a user on Tab 2 ('2. Containment') and click 'Pull Events (AD + Entra + Google)', or click 'View Event Code Guide' to browse all deciphered Windows AD, Entra ID, and Google Workspace security event codes and recommended actions."
    }
}

$btnClearEvents.Add_Click({
    Clear-SecurityEventsResults
    Write-AppLog "Cleared Event Triage table." "INFO"
})

$btnRestorePulledEvents.Add_Click({
    if ($script:savedUserPulledEvents -and $script:savedUserPulledEvents.Count -gt 0) {
        $script:allPulledEvents = @($script:savedUserPulledEvents)
        Render-SecurityEventsGrid
        if ($gridEvents.Rows.Count -gt 0) {
            $gridEvents.Rows[0].Selected = $true
        }
        $targetName = if ($script:currentUser) { $script:currentUser.DisplayName } else { "user" }
        Write-AppLog "Restored $($script:allPulledEvents.Count) previously pulled security event(s) for '$targetName' (no re-query required)." "INFO"
    }
})

function Render-SecurityEventsGrid {
    $gridEvents.Rows.Clear()
    $script:filteredEvents = @()
    $srcFilter = if ($cmbEventSourceFilter -and $cmbEventSourceFilter.SelectedIndex -gt 0) { [string]$cmbEventSourceFilter.SelectedItem } else { "All Sources" }
    $sevFilter = if ($cmbEventSeverityFilter -and $cmbEventSeverityFilter.SelectedIndex -gt 0) { [string]$cmbEventSeverityFilter.SelectedItem } else { "All Severities" }

    $critCount = 0
    $warnCount = 0
    foreach ($ev in $script:allPulledEvents) {
        if ($null -eq $ev) { continue }
        if ($ev.Severity -eq "CRITICAL") { $critCount++ }
        elseif ($ev.Severity -eq "WARNING") { $warnCount++ }

        if ($srcFilter -ne "All Sources" -and $ev.Source -ne $srcFilter) { continue }
        if ($sevFilter -ne "All Severities" -and $ev.Severity -ne $sevFilter) { continue }

        $script:filteredEvents += $ev
        $rIdx = $gridEvents.Rows.Add()
        if ($rIdx -ge 0) {
            $eRow = $gridEvents.Rows[$rIdx]
            $eRow.Cells[0].Value = [string]$ev.Timestamp
            $eRow.Cells[1].Value = [string]$ev.Source
            $eRow.Cells[2].Value = [string]$ev.EventCode
            $eRow.Cells[3].Value = [string]$ev.Severity
            $eRow.Cells[4].Value = [string]$ev.HostOrIP
            $eRow.Cells[5].Value = [string]$ev.Meaning

            $sevCell = $eRow.Cells[3]
            if ($ev.Severity -eq "CRITICAL") {
                $sevCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(248, 113, 113)
            } elseif ($ev.Severity -eq "WARNING") {
                $sevCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(250, 204, 21)
            } else {
                $sevCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(56, 189, 248)
            }
        }
    }
    $lblEventStats.Text = "Showing $($script:filteredEvents.Count) of $($script:allPulledEvents.Count) event(s) | CRITICAL: $critCount | WARNING: $warnCount. Click any row to decipher."
}

$cmbEventSourceFilter.Add_SelectedIndexChanged({ Render-SecurityEventsGrid })
$cmbEventSeverityFilter.Add_SelectedIndexChanged({ Render-SecurityEventsGrid })

$gridEvents.Add_SelectionChanged({
    try {
        if ($null -eq $gridEvents.SelectedRows -or $gridEvents.SelectedRows.Count -le 0) { return }
        $selRow = $gridEvents.SelectedRows[0]
        if ($null -eq $selRow) { return }
        $idx = $selRow.Index
        if ($idx -ge 0 -and $idx -lt $script:filteredEvents.Count) {
            $ev = $script:filteredEvents[$idx]
            if ($null -ne $ev) {
                $nl = [System.Environment]::NewLine
                $txtEventDecision.Text = "EVENT CODE   : [$($ev.Source)] $($ev.EventCode)  |  SEVERITY: $($ev.Severity)  |  TIME: $($ev.Timestamp)$nl" +
                                         "HOST / IP    : $($ev.HostOrIP)$nl" +
                                         "WHAT IT MEANS: $($ev.Meaning)$nl" +
                                         "RECOMMENDED DECISION: $($ev.Decision)$nl" +
                                         "RAW TELEMETRY: $($ev.RawDetail)"
            }
        }
    } catch {}
})

$btnPullSecurityEvents.Add_Click({
    if ($null -eq $script:currentUser) { return }
    $lblEventStats.Text = "Querying AD LDAP/DC Security Logs, Microsoft Entra ID Sign-In/Audit/Risk APIs, and Google GAM7 (max 15s)..."
    $txtEventDecision.Text = "Pulling security events for '$($script:currentUser.DisplayName)' across Active Directory, Microsoft Entra ID, and Google Workspace..."
    Write-AppLog "=== ACTION: PULL SECURITY EVENTS (AD + ENTRA + GOOGLE) ===" "INFO"
    Write-AppLog "Querying bounded security telemetry for '$($script:currentUser.UserPrincipalName)'..." "INFO"
    $form.Refresh()
    [System.Windows.Forms.Application]::DoEvents()
    try {
        $pulledRes = Get-UserSecurityEventsSafe -UserObj $script:currentUser -Server $script:targetServer -Cred $script:adCredential
        $pulled = if ($null -eq $pulledRes) { @() } elseif ($pulledRes -is [array]) { $pulledRes } else { @($pulledRes) }
        $script:allPulledEvents = $pulled
        $script:savedUserPulledEvents = @($pulled)
        if ($btnRestorePulledEvents) {
            $btnRestorePulledEvents.Enabled = ($pulled.Count -gt 0)
            $btnRestorePulledEvents.Text = "Show Pulled Events ($($pulled.Count))"
        }
        Render-SecurityEventsGrid
        if ($gridEvents.Rows.Count -gt 0) {
            $gridEvents.Rows[0].Selected = $true
        }
        $msg = "Pulled $($pulled.Count) security event(s) across Active Directory, Microsoft Entra ID, and Google Workspace for '$($script:currentUser.UserPrincipalName)'."
        Write-AppLog "SUCCESS: $msg" "SUCCESS"
        Add-AuditEntry "Pull Security Events" "SUCCESS" $msg
        Show-ActionPopup -ActionTitle "Pull Security Events" -Succeeded $true -Details $msg
    } catch {
        $errMsg = $_.Exception.Message
        $lblEventStats.Text = "Error pulling security events: $errMsg"
        Write-AppLog "ERROR pulling security events: $errMsg" "ERROR"
        Add-AuditEntry "Pull Security Events" "FAILED" $errMsg
        Show-ActionPopup -ActionTitle "Pull Security Events" -Succeeded $false -Details $errMsg
    }
})

$btnLoadReferenceCatalog.Add_Click({
    try {
        Write-AppLog "Loading Security Event Code Reference Guide (AD + Entra ID + Google Workspace)..." "INFO"
        $refCodes = @(
            @{ Source = "Active Directory"; Code = "4624" },
            @{ Source = "Active Directory"; Code = "4625" },
            @{ Source = "Active Directory"; Code = "4740" },
            @{ Source = "Active Directory"; Code = "4768" },
            @{ Source = "Active Directory"; Code = "4769" },
            @{ Source = "Active Directory"; Code = "4771" },
            @{ Source = "Active Directory"; Code = "4776" },
            @{ Source = "Active Directory"; Code = "4720" },
            @{ Source = "Active Directory"; Code = "4724" },
            @{ Source = "Active Directory"; Code = "4725" },
            @{ Source = "Active Directory"; Code = "4738" },
            @{ Source = "Active Directory"; Code = "4648" },
            @{ Source = "Active Directory"; Code = "4778" },
            @{ Source = "Active Directory"; Code = "4779" },
            @{ Source = "Microsoft Entra ID"; Code = "50173" },
            @{ Source = "Microsoft Entra ID"; Code = "50057" },
            @{ Source = "Microsoft Entra ID"; Code = "50126" },
            @{ Source = "Microsoft Entra ID"; Code = "50053" },
            @{ Source = "Microsoft Entra ID"; Code = "50076" },
            @{ Source = "Microsoft Entra ID"; Code = "53003" },
            @{ Source = "Microsoft Entra ID"; Code = "RISK_DETECTION" },
            @{ Source = "Microsoft Entra ID"; Code = "AUDIT_MFA_CHANGE" },
            @{ Source = "Microsoft Entra ID"; Code = "OAUTH_CONSENT_GRANT" },
            @{ Source = "Google Workspace"; Code = "LOGIN_CHALLENGE" },
            @{ Source = "Google Workspace"; Code = "LOGIN_FAILURE" },
            @{ Source = "Google Workspace"; Code = "OAUTH_TOKEN_GRANT" },
            @{ Source = "Google Workspace"; Code = "USER_SUSPENDED" },
            @{ Source = "Google Workspace"; Code = "SIGN_OUT_USER" }
        )
        $catalogList = [System.Collections.Generic.List[psobject]]::new()
        foreach ($rc in $refCodes) {
            $intel = Get-DecodedEventIntelligence -Source $rc.Source -EventCode $rc.Code -RawSummary ""
            $title = if ($intel -and $intel.Title) { $intel.Title } else { $rc.Code }
            $sev = if ($intel -and $intel.Severity) { $intel.Severity } else { "INFO" }
            $meaning = if ($intel -and $intel.Meaning) { $intel.Meaning } else { "Reference guide entry for $($rc.Code)." }
            $dec = if ($intel -and $intel.Decision) { $intel.Decision } else { "Refer to security response playbook." }
            $catalogList.Add([PSCustomObject]@{
                Timestamp = "REFERENCE GUIDE"
                Source    = $rc.Source
                EventCode = "$($rc.Code) ($title)"
                Severity  = $sev
                HostOrIP  = "Reference"
                Meaning   = $meaning
                Decision  = $dec
                RawDetail = "Reference guide entry for $($rc.Source) code $($rc.Code). Select a user on Tab 2 and click 'Pull Events (AD + Entra + Google)' to query environment logs."
            })
        }
        $script:allPulledEvents = $catalogList.ToArray()
        Render-SecurityEventsGrid
        if ($gridEvents.Rows.Count -gt 0) {
            $gridEvents.Rows[0].Selected = $true
        }
        if ($btnRestorePulledEvents -and $script:savedUserPulledEvents -and $script:savedUserPulledEvents.Count -gt 0) {
            $btnRestorePulledEvents.Enabled = $true
            $btnRestorePulledEvents.Text = "Show Pulled Events ($($script:savedUserPulledEvents.Count))"
        }
        Write-AppLog "Loaded $($catalogList.Count) reference security event codes into the Event Triage table. Click 'Show Pulled Events' to return to user query results." "SUCCESS"
    } catch {
        Write-AppLog "Error rendering Event Code Guide: $($_.Exception.Message)" "ERROR"
        Show-ActionPopup -ActionTitle "View Event Code Guide" -Succeeded $false -Details $_.Exception.Message
    }
})

function Update-ExtendedTabsUserHeader {
    if ($null -eq $script:currentUser) {
        if ($lblLockdownTarget) { $lblLockdownTarget.Text = "Target User: (No user selected - select and verify a user on Tab 2 '2. Containment')" }
        if ($lblLockdownADMeta) { $lblLockdownADMeta.Text = "AD Account Expires: --  |  Allowed Logon Workstations: --  |  Safety Lock: LOCKED" }
        if ($lblEventsTarget) { $lblEventsTarget.Text = "Target User: (No user selected - select a user on Tab 2 '2. Containment' to pull events)" }
        return
    }
    $u = $script:currentUser
    $lockState = if ($chkVerified.Checked) { "UNLOCKED (Verified)" } else { "LOCKED (Check confirmation box on Tab 2)" }
    if ($lblLockdownTarget) {
        $lblLockdownTarget.Text = "Target: $($u.DisplayName)  |  AD sAM: $($u.SamAccountName)  |  Entra: $($u.GraphTargetId)  |  Google: $($u.GamTargetId)"
    }
    if ($lblLockdownADMeta) {
        $lblLockdownADMeta.Text = "AD Expires: $($u.AccountExpiresDisplay)  |  LogonWorkstations: $($u.LogonWorkstationsDisplay)  |  Deck: $lockState"
    }
    if ($lblEventsTarget) {
        $lblEventsTarget.Text = "Target: $($u.DisplayName) (sAM: $($u.SamAccountName) | UPN: $($u.UserPrincipalName) | Mail: $($u.Mail))"
    }
    if ($btnPullSecurityEvents) {
        $btnPullSecurityEvents.Enabled = $true
    }
}

