function Load-AuditGrid {
    $gridAudit.Rows.Clear()
    $totalCount = 0
    $successCount = 0
    $failCount = 0

    $filterText = if ($txtAuditFilter -and $txtAuditFilter.Text) { $txtAuditFilter.Text.Trim().ToLowerInvariant() } else { "" }
    $statusFilter = if ($cmbAuditStatus -and $cmbAuditStatus.SelectedIndex -gt 0) { [string]$cmbAuditStatus.SelectedItem } else { "All Statuses" }

    $rowsToRender = [System.Collections.Generic.List[psobject]]::new()
    $seenKeys = @{}

    $candidateCsvPaths = @(
        "$env:ProgramData\IncidentResponse-Automator\AuditLog.csv",
        "$env:LOCALAPPDATA\IncidentResponse-Automator\AuditLog.csv",
        $script:auditCsv
    ) | Select-Object -Unique

    foreach ($csvPath in $candidateCsvPaths) {
        if (-not [string]::IsNullOrWhiteSpace($csvPath) -and (Test-Path $csvPath)) {
            try {
                $csvRows = @(Import-Csv -Path $csvPath -ErrorAction SilentlyContinue)
                foreach ($cr in $csvRows) {
                    if ($null -eq $cr -or (-not $cr.Timestamp -and -not $cr.Action)) { continue }
                    $k = "$($cr.Timestamp)|$($cr.Action)|$($cr.TargetUPN)|$($cr.Status)"
                    if (-not $seenKeys.ContainsKey($k)) {
                        $seenKeys[$k] = $true
                        $rowsToRender.Add($cr)
                    }
                }
            } catch {}
        }
    }

    if ($null -ne $script:inMemoryAuditLog -and $script:inMemoryAuditLog.Count -gt 0) {
        foreach ($mr in $script:inMemoryAuditLog) {
            if ($null -eq $mr) { continue }
            $k = "$($mr.Timestamp)|$($mr.Action)|$($mr.TargetUPN)|$($mr.Status)"
            if (-not $seenKeys.ContainsKey($k)) {
                $seenKeys[$k] = $true
                $rowsToRender.Add($mr)
            }
        }
    }

    if ($rowsToRender.Count -gt 0) {
        $arrRows = $rowsToRender.ToArray()
        [array]::Reverse($arrRows)
        foreach ($r in $arrRows) {
            if (-not $r.Timestamp -and -not $r.Action) { continue }
            $totalCount++
            if ($r.Status -eq "SUCCESS") { $successCount++ }
            elseif ($r.Status -eq "FAILED" -or $r.Status -eq "PARTIAL") { $failCount++ }

            if ($statusFilter -ne "All Statuses" -and $r.Status -ne $statusFilter) {
                continue
            }
            if (-not [string]::IsNullOrEmpty($filterText)) {
                $combined = ("$($r.Timestamp) $($r.Admin) $($r.TargetUPN) $($r.TargetName) $($r.Action) $($r.Status) $($r.Details)").ToLowerInvariant()
                if (-not $combined.Contains($filterText)) {
                    continue
                }
            }

            $rowIdx = $gridAudit.Rows.Add()
            if ($rowIdx -ge 0) {
                $aRow = $gridAudit.Rows[$rowIdx]
                $aRow.Cells[0].Value = [string]$r.Timestamp
                $aRow.Cells[1].Value = [string]$r.Admin
                $aRow.Cells[2].Value = [string]$r.TargetUPN
                $aRow.Cells[3].Value = [string]$r.TargetName
                $aRow.Cells[4].Value = [string]$r.Action
                $aRow.Cells[5].Value = [string]$r.Status
                $aRow.Cells[6].Value = [string]$r.Details

                $statusCell = $aRow.Cells[5]
                if ($r.Status -eq "SUCCESS") {
                    $statusCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(34, 197, 94)
                } elseif ($r.Status -eq "PARTIAL") {
                    $statusCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(234, 179, 8)
                } elseif ($r.Status -eq "FAILED") {
                    $statusCell.Style.ForeColor = [System.Drawing.Color]::FromArgb(248, 113, 113)
                }
            }
        }
    }
    if ($lblAuditSummary) {
        $lblAuditSummary.Text = "Total: $totalCount  |  Success: $successCount  |  Failed/Partial: $failCount"
    }
}

