$btnOpenAuditFolder.Size = New-Object System.Drawing.Size(192, 36)
$btnOpenAuditFolder.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
$btnOpenAuditFolder.BackColor = [System.Drawing.Color]::FromArgb(241, 245, 249)
$btnOpenAuditFolder.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$tabAudit.Controls.Add($btnOpenAuditFolder)

$btnViewAuditDetail = New-Object System.Windows.Forms.Button
$btnViewAuditDetail.Text = "Inspect Selected Entry"
$btnViewAuditDetail.Location = New-Object System.Drawing.Point(633, 476)
$btnViewAuditDetail.Size = New-Object System.Drawing.Size(192, 36)
$btnViewAuditDetail.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
$btnViewAuditDetail.BackColor = [System.Drawing.Color]::FromArgb(241, 245, 249)
$btnViewAuditDetail.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$tabAudit.Controls.Add($btnViewAuditDetail)

function Show-SelectedAuditDetail {
    if ($gridAudit.SelectedRows.Count -le 0) {
        [System.Windows.Forms.MessageBox]::Show($form, "Select an audit log row in the table above to inspect its full details.", "Audit Trail Entry", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
        return
    }
    $sel = $gridAudit.SelectedRows[0]
    $nl = [System.Environment]::NewLine
    $detailText = "Timestamp : $($sel.Cells[0].Value)$nl" +
                  "Operator  : $($sel.Cells[1].Value)$nl" +
                  "Target ID : $($sel.Cells[2].Value)$nl" +
                  "User Name : $($sel.Cells[3].Value)$nl" +
                  "Action    : $($sel.Cells[4].Value)$nl" +
                  "Status    : $($sel.Cells[5].Value)$nl$nl" +
                  "Verification Details:$nl$($sel.Cells[6].Value)"
    [System.Windows.Forms.MessageBox]::Show($form, $detailText, "Audit Log Entry Inspection", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
}

$btnViewAuditDetail.Add_Click({ Show-SelectedAuditDetail })
$gridAudit.Add_CellDoubleClick({ Show-SelectedAuditDetail })

$btnRefreshAudit.Add_Click({
    Load-AuditGrid
    Write-AppLog "Audit Trail refreshed ($($gridAudit.Rows.Count) row(s) displayed)." "INFO"
})

$btnOpenAuditFolder.Add_Click({
    if (Test-Path $script:auditDir) {
        Start-Process "explorer.exe" -ArgumentList $script:auditDir
    }
})

$btnExportAudit.Add_Click({
    $saveDlg = New-Object System.Windows.Forms.SaveFileDialog
    $saveDlg.Filter = "CSV Files (*.csv)|*.csv|All Files (*.*)|*.*"
    $saveDlg.FileName = "IncidentAuditLog-$((Get-Date).ToString('yyyyMMdd-HHmmss')).csv"
    if ($saveDlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        Copy-Item -Path $script:auditCsv -Destination $saveDlg.FileName -Force
        Write-AppLog "Audit log exported to: $($saveDlg.FileName)" "SUCCESS"
        Show-ActionPopup -ActionTitle "Export Audit Log" -Succeeded $true -Details "Audit log exported to $($saveDlg.FileName)"
    }
})

$tabControl.Add_SelectedIndexChanged({
    if ($tabControl.SelectedTab -eq $tabAudit) {
        Load-AuditGrid
    } elseif ($tabControl.SelectedTab -eq $tabLockdown -or $tabControl.SelectedTab -eq $tabEvents) {
        Update-ExtendedTabsUserHeader
    } elseif ($tabControl.SelectedTab -eq $tabIncident) {
        if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
            Update-IntegrationAlertBanner
        }
    }
})

# Dynamic Theme Engine (Dark Mode / Light Mode)
$script:isDark = $true

function Apply-AppTheme {
    param([bool]$Dark)

    $bgForm = if ($Dark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(248, 250, 252) }
    $bgCard = if ($Dark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $bgInput = if ($Dark) { [System.Drawing.Color]::FromArgb(2, 6, 23) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $fgText = if ($Dark) { [System.Drawing.Color]::FromArgb(248, 250, 252) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $fgSub = if ($Dark) { [System.Drawing.Color]::FromArgb(148, 163, 184) } else { [System.Drawing.Color]::FromArgb(71, 85, 105) }
    $fgLabel = if ($Dark) { [System.Drawing.Color]::FromArgb(226, 232, 240) } else { [System.Drawing.Color]::FromArgb(51, 65, 85) }

    $form.BackColor = $bgForm
    $tabControl.BackColor = $bgForm
    $tabIncident.BackColor = $bgForm
    $tabDiag.BackColor = $bgForm
    $tabLockdown.BackColor = $bgForm
    $tabEvents.BackColor = $bgForm
    $tabAudit.BackColor = $bgForm

    $allGrps = @($grpSearch, $grpIdentity, $grpActions, $grpLog, $grpDiagStatus, $grpDiagActions, $grpDiagGuide, $grpLockHeader, $grpExtControls, $grpRulesAudit, $grpEventHeader, $grpEventDecision)
    foreach ($grp in $allGrps) {
        if ($grp) {
            $grp.BackColor = $bgCard
            $grp.ForeColor = $fgText
        }
    }

    if ($lblDiagGuide) { $lblDiagGuide.ForeColor = $fgLabel }

    if ($headerPanel) {
        $headerPanel.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
    }
    if ($lblTitle) {
        $lblTitle.ForeColor = if ($Dark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    }
    if ($lblSub) {
        $lblSub.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(148, 163, 184) } else { [System.Drawing.Color]::FromArgb(71, 85, 105) }
    }
    if ($btnCheckUpdates) {
        $btnCheckUpdates.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(226, 232, 240) }
        $btnCheckUpdates.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(56, 189, 248) } else { [System.Drawing.Color]::FromArgb(2, 132, 199) }
    }
    if ($btnSwitchDomain) {
        $btnSwitchDomain.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(226, 232, 240) }
        $btnSwitchDomain.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(56, 189, 248) } else { [System.Drawing.Color]::FromArgb(2, 132, 199) }
    }

    $bgLogBox = if ($Dark) { [System.Drawing.Color]::FromArgb(2, 6, 23) } else { [System.Drawing.Color]::FromArgb(255, 255, 255) }
    $fgLogBox = if ($Dark) { [System.Drawing.Color]::FromArgb(226, 232, 240) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }

    if ($txtSearch) { $txtSearch.BackColor = $bgInput; $txtSearch.ForeColor = $fgText }
    if ($lstResults) { $lstResults.BackColor = $bgInput; $lstResults.ForeColor = $fgText }
    if ($txtCustomPass) { $txtCustomPass.BackColor = $bgInput; $txtCustomPass.ForeColor = $fgText }
    if ($txtLockWorkstations) { $txtLockWorkstations.BackColor = $bgInput; $txtLockWorkstations.ForeColor = $fgSub }
    if ($txtAuditFilter) { $txtAuditFilter.BackColor = $bgInput; $txtAuditFilter.ForeColor = $fgText }
    if ($cmbAuditStatus) { $cmbAuditStatus.BackColor = $bgInput; $cmbAuditStatus.ForeColor = $fgText }
    if ($cmbEventSourceFilter) { $cmbEventSourceFilter.BackColor = $bgInput; $cmbEventSourceFilter.ForeColor = $fgText }
    if ($cmbEventSeverityFilter) { $cmbEventSeverityFilter.BackColor = $bgInput; $cmbEventSeverityFilter.ForeColor = $fgText }
    if ($txtLog) { $txtLog.BackColor = $bgLogBox; $txtLog.ForeColor = $fgLogBox }
    if ($txtRuleDecision) { $txtRuleDecision.BackColor = $bgLogBox; $txtRuleDecision.ForeColor = $fgLogBox }
    if ($txtEventDecision) { $txtEventDecision.BackColor = $bgLogBox; $txtEventDecision.ForeColor = $fgLogBox }

    if ($lblIdName) { $lblIdName.ForeColor = $fgText }
    if ($lblIdDept) { $lblIdDept.ForeColor = $fgLabel }
    if ($lblSearchStatus) { $lblSearchStatus.ForeColor = $fgSub }
    if ($lblAuditSearch) { $lblAuditSearch.ForeColor = $fgLabel }
    if ($lblAuditPath) { $lblAuditPath.ForeColor = $fgSub }
    if ($lblLockdownTarget) { $lblLockdownTarget.ForeColor = $fgText }
    if ($lblLockdownADMeta) { $lblLockdownADMeta.ForeColor = $fgSub }
    if ($lblWksRestrict) { $lblWksRestrict.ForeColor = $fgLabel }
    if ($lblEventsTarget) { $lblEventsTarget.ForeColor = $fgText }
    if ($lblEventStats) { $lblEventStats.ForeColor = $fgSub }

    $metricPanels = @($pnlCardPass, $pnlCard365, $pnlCardGoogle, $pnlCardAcct)
    foreach ($p in $metricPanels) {
        if ($p) {
            $p.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
        }
    }
    $metricTitles = @($lblCardPassTitle, $lblCard365Title, $lblCardGoogleTitle, $lblCardAcctTitle)
    foreach ($t in $metricTitles) {
        if ($t) { $t.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(148, 163, 184) } else { [System.Drawing.Color]::FromArgb(100, 116, 139) } }
    }
    $metricSubs = @($lblCardPassSub, $lblCard365Sub, $lblCardGoogleSub, $lblCardAcctSub)
    foreach ($s in $metricSubs) {
        if ($s) { $s.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(100, 116, 139) } else { [System.Drawing.Color]::FromArgb(148, 163, 184) } }
    }

    if ($lblCardPassVal) { $lblCardPassVal.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(250, 204, 21) } else { [System.Drawing.Color]::FromArgb(217, 119, 6) } }
    if ($lblCard365Val) { $lblCard365Val.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(56, 189, 248) } else { [System.Drawing.Color]::FromArgb(2, 132, 199) } }
    if ($lblCardGoogleVal) { $lblCardGoogleVal.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(52, 211, 153) } else { [System.Drawing.Color]::FromArgb(5, 150, 105) } }
    if ($lblCardAcctVal) { $lblCardAcctVal.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(248, 113, 113) } else { [System.Drawing.Color]::FromArgb(220, 38, 38) } }

    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }

    $testBtns = @($btnTestAD, $btnTestM365, $btnTestGoogle, $btnRefreshAudit, $btnExportAudit, $btnOpenAuditFolder, $btnViewAuditDetail, $btnClearAuditFilter, $btnRefreshUserSessions, $btnClearRules, $btnLoadReferenceCatalog, $btnRestorePulledEvents, $btnClearEvents)
    foreach ($b in $testBtns) {
        if ($b) {
            $b.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
            $b.ForeColor = if ($Dark) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
        }
    }

    $allGrids = @($gridAudit, $gridRules, $gridEvents)
    foreach ($g in $allGrids) {
        if ($g) {
            $g.BackgroundColor = $bgInput
            $g.DefaultCellStyle.BackColor = $bgCard
            $g.DefaultCellStyle.ForeColor = $fgText
            $g.DefaultCellStyle.SelectionBackColor = [System.Drawing.Color]::FromArgb(37, 99, 235)
            $g.DefaultCellStyle.SelectionForeColor = [System.Drawing.Color]::White
            $g.AlternatingRowsDefaultCellStyle.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(241, 245, 249) }
            $g.AlternatingRowsDefaultCellStyle.ForeColor = $fgText
            $g.ColumnHeadersDefaultCellStyle.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(2, 6, 23) } else { [System.Drawing.Color]::FromArgb(226, 232, 240) }
            $g.ColumnHeadersDefaultCellStyle.ForeColor = $fgText
        }
    }

    if ($btnThemeToggle) {
        $btnThemeToggle.Text = if ($Dark) { "[ Light Mode ]" } else { "[ Dark Mode ]" }
        $btnThemeToggle.BackColor = if ($Dark) { [System.Drawing.Color]::FromArgb(51, 65, 85) } else { [System.Drawing.Color]::FromArgb(30, 41, 59) }
        $btnThemeToggle.ForeColor = if ($Dark) { [System.Drawing.Color]::FromArgb(250, 204, 21) } else { [System.Drawing.Color]::FromArgb(148, 163, 184) }
    }
}

$btnThemeToggle.Add_Click({
    $script:isDark = -not $script:isDark
    Apply-AppTheme $script:isDark
})

# =============================================================================
# RESPONSIVE PROPORTIONAL LAYOUT & PIXEL-SAFE FONT SCALING ENGINE (1080p / 1440p / 4K / Full-Screen)
# =============================================================================
$script:baseClientWidth  = 874.0
$script:baseClientHeight = 868.0
$script:responsiveMap    = [System.Collections.Generic.List[psobject]]::new()
$script:pixelFontCache   = @{}
$script:lastFontScale    = -1.0
$script:isUpdatingLayout = $false

function Get-CachedPixelFont {
    param(
        [string]$FamilyName = "Segoe UI",
        [double]$PixelSize = 12.0,
        [System.Drawing.FontStyle]$Style = [System.Drawing.FontStyle]::Regular
    )
    $roundedPx = [Math]::Max(8.5, [Math]::Round($PixelSize * 2.0) / 2.0)
    $key = "$FamilyName|$([int]$Style)|$roundedPx"
    if (-not $script:pixelFontCache.ContainsKey($key)) {
        try {
            $script:pixelFontCache[$key] = New-Object System.Drawing.Font($FamilyName, [single]$roundedPx, $Style, [System.Drawing.GraphicsUnit]::Pixel)
        } catch {
            $script:pixelFontCache[$key] = New-Object System.Drawing.Font("Segoe UI", [single]$roundedPx, [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)
        }
    }
    return $script:pixelFontCache[$key]
}

function Register-ResponsiveControlTree {
    param([System.Windows.Forms.Control]$ParentControl)
    if ($null -eq $ParentControl) { return }
    foreach ($ctrl in $ParentControl.Controls) {
        if ($null -eq $ctrl) { continue }
        if (-not ($ctrl -is [System.Windows.Forms.TabPage])) {
            $fFam = if ($ctrl.Font -and $ctrl.Font.FontFamily) { [string]$ctrl.Font.FontFamily.Name } else { "Segoe UI" }
            $fPt  = if ($ctrl.Font) { [double]$ctrl.Font.SizeInPoints } else { 9.0 }
            $fSty = if ($ctrl.Font) { $ctrl.Font.Style } else { [System.Drawing.FontStyle]::Regular }
            $script:responsiveMap.Add([PSCustomObject]@{
                Control    = $ctrl
                X          = [double]$ctrl.Location.X
                Y          = [double]$ctrl.Location.Y
                W          = [double]$ctrl.Size.Width
                H          = [double]$ctrl.Size.Height
                FontFamily = $fFam
                FontPt     = $fPt
                FontStyle  = $fSty
            })
        }
        if ($ctrl.Controls -and $ctrl.Controls.Count -gt 0) {
            Register-ResponsiveControlTree -ParentControl $ctrl
        }
    }
}

Register-ResponsiveControlTree -ParentControl $form

function Update-ResponsiveLayout {
    param([switch]$ForceFontUpdate)
    if ($script:isUpdatingLayout) { return }
    if ($null -eq $form -or $form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { return }
    if ($form.ClientSize.Width -lt 200 -or $form.ClientSize.Height -lt 200) { return }

    $script:isUpdatingLayout = $true
    try {
        $scaleX = [double]$form.ClientSize.Width / $script:baseClientWidth
        $scaleY = [double]$form.ClientSize.Height / $script:baseClientHeight
        if ($scaleX -lt 0.75) { $scaleX = 0.75 }
        if ($scaleY -lt 0.75) { $scaleY = 0.75 }

        $minScale = [Math]::Min($scaleX, $scaleY)
        $updateFonts = $ForceFontUpdate.IsPresent -or ([Math]::Abs($minScale - $script:lastFontScale) -ge 0.025)

        $form.SuspendLayout()
        try {
            if ($tabControl) {
                $newTabW = [int][Math]::Round(850.0 * $scaleX)
                $tabItemW = [int][Math]::Max(110, [Math]::Floor(($newTabW - 26) / 5.0))
                $tabItemH = [int][Math]::Max(24, [Math]::Round(28.0 * $scaleY))
                $tabControl.ItemSize = New-Object System.Drawing.Size($tabItemW, $tabItemH)
            }

            foreach ($item in $script:responsiveMap) {
                $c = $item.Control
                if ($null -eq $c -or $c.IsDisposed) { continue }

                $nx = [int][Math]::Round($item.X * $scaleX)
                $ny = [int][Math]::Round($item.Y * $scaleY)
                $nw = [int][Math]::Max(16, [Math]::Round($item.W * $scaleX))
                $nh = [int][Math]::Max(14, [Math]::Round($item.H * $scaleY))
                $c.Bounds = New-Object System.Drawing.Rectangle($nx, $ny, $nw, $nh)

                if ($updateFonts) {
                    # Use Pixel graphics unit so Windows 125%/150%/200% DPI never clips text inside controls
                    $pxSize = $item.FontPt * 1.24 * $minScale
                    $c.Font = Get-CachedPixelFont -FamilyName $item.FontFamily -PixelSize $pxSize -Style $item.FontStyle
                }
            }

            if ($updateFonts) {
                $gridCellFont = Get-CachedPixelFont -FamilyName "Segoe UI" -PixelSize (8.5 * 1.24 * $minScale) -Style ([System.Drawing.FontStyle]::Regular)
                $gridHdrFont  = Get-CachedPixelFont -FamilyName "Segoe UI" -PixelSize (8.5 * 1.24 * $minScale) -Style ([System.Drawing.FontStyle]::Bold)
                $rowH = [int][Math]::Max(22, [Math]::Round(24.0 * $minScale))
                foreach ($g in @($gridRules, $gridEvents, $gridAudit)) {
                    if ($g) {
                        $g.DefaultCellStyle.Font = $gridCellFont
                        $g.ColumnHeadersDefaultCellStyle.Font = $gridHdrFont
                        $g.RowTemplate.Height = $rowH
                        $g.ColumnHeadersHeight = [int][Math]::Max(26, [Math]::Round(28.0 * $minScale))
                    }
                }
                $script:lastFontScale = $minScale
            }
        } finally {
            $form.ResumeLayout($true)
        }
    } catch {} finally {
        $script:isUpdatingLayout = $false
    }
}

$form.Add_Resize({
    Update-ResponsiveLayout
})

# Pre-Flight Checks run asynchronously via WinForms Timer after window renders
$form.Add_Shown({
    $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal
    try {
        $workArea = [System.Windows.Forms.Screen]::FromControl($form).WorkingArea
        $targetClientH = [int][Math]::Min([Math]::Max(760, [int][Math]::Round($workArea.Height * 0.86)), 1560)
        $targetClientW = [int][Math]::Min([Math]::Max(940, [int][Math]::Round($targetClientH * 1.12)), [int][Math]::Round($workArea.Width * 0.88))
        $form.ClientSize = New-Object System.Drawing.Size($targetClientW, $targetClientH)
        $form.Location = New-Object System.Drawing.Point(
            [int]($workArea.Left + [Math]::Max(0, ($workArea.Width - $form.Width) / 2)),
            [int]($workArea.Top + [Math]::Max(0, ($workArea.Height - $form.Height) / 2))
        )
    } catch {}
    Update-ResponsiveLayout -ForceFontUpdate

    $form.TopMost = $true
    $form.Activate()
    $form.BringToFront()
    $form.TopMost = $false

    Apply-AppTheme $true
    Load-AuditGrid
    Write-AppLog "Incident Response Automator GUI loaded. Running Pre-Flight Verification..." "INFO"
    $form.Refresh()
    [System.Windows.Forms.Application]::DoEvents()

    Hide-ConsoleWindowSafe

    $script:startupTimer = New-Object System.Windows.Forms.Timer
    $script:startupTimer.Interval = 150
    $script:startupTimer.Add_Tick({
        $script:startupTimer.Stop()
        $script:startupTimer.Dispose()

        $unlinkedIntegrations = [System.Collections.Generic.List[string]]::new()

        # 1. Verify Active Directory Connectivity
        $adCheck = Invoke-VerifyAD -QuickStartup
        if ($adCheck.Verified) {
            $script:targetDomain = $adCheck.Domain
            $lblSub.Text = "Domain: $($script:targetDomain) | Admin: $($script:adminAccount)"
            $lblStatusAD.Text = "Active Directory: VERIFIED ($($adCheck.Domain) via $($adCheck.Engine))"
            $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            Write-AppLog "Pre-Flight [1/3]: Active Directory [VERIFIED: $($adCheck.Domain) ($($adCheck.Engine))]" "SUCCESS"
        } else {
            $lblStatusAD.Text = "Active Directory: NOT CONNECTED ($($adCheck.Error))"
            $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
            if ($script:savedDomainConfig -and ($script:savedDomainConfig.TargetDomain -or $script:savedDomainConfig.TargetServer)) {
                $remDom = if ($script:savedDomainConfig.TargetDomain) { $script:savedDomainConfig.TargetDomain } else { $script:savedDomainConfig.TargetServer }
                $remUser = if ($script:savedDomainConfig.AdminUsername) { $script:savedDomainConfig.AdminUsername } else { $script:adminAccount }
                $lblSub.Text = "Domain: $remDom | Operator: $remUser"
                Write-AppLog "Pre-Flight [1/3]: Loaded remembered domain '$remDom' (Operator: '$remUser'). Password authentication required. Click 'Switch Domain / DC' to connect." "INFO"
            } else {
                Write-AppLog "Pre-Flight [1/3]: Active Directory not connected ($($adCheck.Error)). Click 'Switch Domain / DC' or check Tab 1 ('1. Setup')." "WARN"
            }
            $unlinkedIntegrations.Add("Active Directory: $($adCheck.Error)")
        }
        [System.Windows.Forms.Application]::DoEvents()

        # 2. Verify Microsoft Graph SDK & Scopes
        $graphCheck = Invoke-VerifyGraph -QuickStartup
        if ($graphCheck.Verified) {
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($($graphCheck.Account))"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            Write-AppLog "Pre-Flight [2/3]: Microsoft Graph [VERIFIED: $($graphCheck.Account)]" "SUCCESS"
        } else {
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: NOT VERIFIED ($($graphCheck.Error))"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
            Write-AppLog "Pre-Flight [2/3]: Microsoft Graph not ready: $($graphCheck.Error)" "WARN"
            $unlinkedIntegrations.Add("Microsoft Graph (365/Entra): $($graphCheck.Error)")
        }
        [System.Windows.Forms.Application]::DoEvents()

        # 3. Verify GAM7 Installation & Google OAuth
        $gamCheck = Invoke-VerifyGAM -QuickStartup
        if ($gamCheck.Verified) {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): VERIFIED (v$($gamCheck.Version) & OAuth Ready)"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            Write-AppLog "Pre-Flight [3/3]: Google GAM7 [VERIFIED: v$($gamCheck.Version) at $($gamCheck.Executable)]" "SUCCESS"
        } else {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): NOT VERIFIED ($($gamCheck.Error))"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
            Write-AppLog "Pre-Flight [3/3]: Google GAM7 not ready: $($gamCheck.Error)" "WARN"
            $unlinkedIntegrations.Add("Google Workspace (GAM7): $($gamCheck.Error)")
        }

        if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
            Update-IntegrationAlertBanner
        }

        if ($unlinkedIntegrations.Count -gt 0) {
            Write-AppLog "NOTICE: $($unlinkedIntegrations.Count) integration(s) not ready. Use Tab 1 ('1. Setup') or 'Switch Domain / DC' to link accounts." "WARN"
            $tabControl.SelectedTab = $tabDiag
        } else {
            Write-AppLog "All 3 integrations verified. Opening Tab 2 ('2. Containment'). Enter at least 3 characters above and click 'Find Users'." "SUCCESS"
            $tabControl.SelectedTab = $tabIncident
        }
    })
    $script:startupTimer.Start()
})

try {
    [void]$form.ShowDialog()
} catch {
    $nl = [System.Environment]::NewLine
    [System.Windows.Forms.MessageBox]::Show(
        "Failed to start Security Incident Response Automator:$nl$nl$($_.Exception.Message)",
        "Incident Response Automator - Startup Error",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Error
    ) | Out-Null
    exit 1
}

